--
-- Table structure for table `discount_rates`
--

DROP TABLE IF EXISTS `discount_rates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `discount_rates` (
  `discount_rate_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `discount_rate_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '論理削除用\r\n日付が入っている場合は論理削除',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
