  `product_category_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '商品カテゴリーのID',
  `parent_category_id` bigint unsigned DEFAULT NULL,
  `product_category_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品カテゴリーの名称',
  `display_order` bigint DEFAULT NULL,
  `link_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
