--
-- Table structure for table `product_color_pictures`
--

DROP TABLE IF EXISTS `product_color_pictures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `product_color_pictures` (
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `picture_id` bigint unsigned NOT NULL,
  `color_id` bigint unsigned NOT NULL,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `display_order` bigint DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_product_color_pictures_01` (`product_id`,`picture_id`,`color_id`,`display_order`),
  KEY `picture_id` (`picture_id`),
  KEY `color_id` (`color_id`),
  CONSTRAINT `product_color_pictures_ibfk_1` FOREIGN KEY (`color_id`) REFERENCES `colors` (`color_id`),
  CONSTRAINT `product_color_pictures_ibfk_2` FOREIGN KEY (`picture_id`) REFERENCES `pictures` (`picture_id`),
  CONSTRAINT `product_color_pictures_ibfk_3` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

