INSERT INTO `product_html_parts` VALUES (4,4,'【ポスターフレーム】ポスターフレームスタンダード','<section class=\"article__content\">\r\n  <h3 class=\"section__caption c-heading--sm\">共通仕様</h3>\r\n  <table class=\"c-table--sm u-width--70\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\">飾る方向</th>\r\n        <td>縦横共用</td>\r\n      </tr>\r\n      <tr>\r\n        <th>板厚</th>\r\n        <td>表3mm、裏5mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th nowrap>飾る物の厚さ</th>\r\n        <td>最大0.5mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th nowrap>飾る物とフレームの余白</th>\r\n        <td>	上下左右25mmずつ</td>\r\n      </tr>\r\n      <tr>\r\n        <th nowrap>固定ネジ箇所数</th>\r\n        <td>固定ネジ4～8ヶ所。壁掛け金具2個。</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</section>\r\n<section class=\"article__content\">\r\n  <h3 class=\"section__caption c-heading--sm\">サイズ別仕様</h3>\r\n  <table class=\"c-table--sm\">\r\n    <tbody>\r\n      <tr>\r\n        <th ></th>\r\n        <th>飾る物の目安サイズ</th>\r\n        <th>製品全体のサイズ</th>\r\n        <th>重量</th>\r\n        <th>図面</th>\r\n      </tr>\r\n      <tr>\r\n        <th>A3</th>\r\n        <td>420×297mm</td>\r\n        <td>470×347mm</td>\r\n        <td>約1.6kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_A3\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_A3\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_A3_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>A2</th>\r\n        <td>594×420mm</td>\r\n        <td>644×470mm</td>\r\n        <td>約2.9kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_A2\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_A2\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_A2_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>A1</th>\r\n        <td>841×594mm</td>\r\n        <td>960×660mm</td>\r\n        <td>約6.0kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_A1\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_A1\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_A1_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>A0</th>\r\n        <td>1189×841mm</td>\r\n        <td>1239×891mm</td>\r\n        <td>約10.5kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_A0\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_A0\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_A0_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>B4</th>\r\n        <td>364×257mm</td>\r\n        <td>414×307mm</td>\r\n        <td>約1.2kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_B4\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_B4\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_B4_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>B3</th>\r\n        <td>515×364mm</td>\r\n        <td>565×414mm</td>\r\n        <td>約2.3kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_B3\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_B3\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_B3_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>B2</th>\r\n        <td>728×515mm</td>\r\n        <td>778×565mm</td>\r\n        <td>約4.2kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_B2\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_B2\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_B2_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n      <tr>\r\n        <th>B1</th>\r\n        <td>1030×728mm</td>\r\n        <td>1080×778mm</td>\r\n        <td>約8.0kg</td>\r\n        <td class=\"js-modal\"><a data-target=\"zumen_B1\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n          <div id=\"zumen_B1\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_B1_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n        </td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n  <div class=\"article__content\">\r\n    <p class=\"c-text--left u-margin--top-8\">\r\n      <a data-target=\"sunpo_0\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n        <div id=\"sunpo_0\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n    </p>\r\n    <p class=\"c-text--left u-margin--top-8\">\r\n      <a class=\"c-button--sm-white\" href=\"/storage/images/poster/poster_std/poster_frame_std_manual.pdf\" target=\"_blank\">組立方法</a>\r\n    </p>\r\n  </div>\r\n</section>\r\n<section class=\"article__content\">\r\n  <h3 class=\"section__caption c-heading--sm u-margin--top-32\">ご希望サイズが無い場合</h3>\r\n  <div class=\"l-article--column-1\">\r\n    <ul class=\"article__content c-list--disc\">\r\n      <li class=\"list__item\">ご希望のサイズやカラーが無い場合は<a href=\"/products/detail/282/\" target=\"_blank\">ポスターフレームスタンダード セミオーダー</a>をご利用下さい。</li>\r\n    </ul>\r\n  </div>\r\n</section>','2019-05-15 06:37:08','2020-12-04 04:42:52'),(5,2,'【ポスターフレーム】ポスターフレームスタンダード（当日出荷あり）','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <div class=\"article__content\">\r\n        <h3 class=\"c-heading--sm\">シンプル設計</h3>\r\n        <ul class=\"c-list--disc\">\r\n          <li class=\"list__item\">アクリル板にポスターを挟み込むシンプル設計のポスターフレーム。縁が無い為、飾る物を際立たせてくれます。</li>\r\n          <li class=\"list__item\">ポスターフレームのシンプルなスタイルは飾る場所を選びません。</li>\r\n        </ul>\r\n      <div>\r\n      <div class=\"article__content\">\r\n        <h3 class=\"c-heading--sm\">選べる飾り方</h3>\r\n        <ul class=\"c-list--disc\">\r\n          <li class=\"list__item\">厚さ8mm（表3mm＋裏5mm）の丈夫な作りです。壁掛けや立て掛けなど、縦・横どちらでも使用できます。</li>\r\n          <li class=\"list__item\">縦・横のどちらの向きでも使用可能な金具が付属します。</li>\r\n        </ul>\r\n      <div>\r\n      <div class=\"article__content\">\r\n        <h3 class=\"c-heading--sm\">色褪せを防止</h3>\r\n        <ul class=\"c-list--disc\">\r\n          <li class=\"list__item\">ポスターの色褪せを防ぐ紫外線カット（UVカット）を表板として選択が可能。大切なポスターをいつまでも安心して飾ることができます。</li>\r\n        </ul>\r\n      <div>\r\n      <div class=\"article__content\">\r\n        <h3 class=\"c-heading--sm\">スタンドで飾る</h3>\r\n        <ul class=\"c-list--disc\">\r\n          <li class=\"list__item\">B4、A3サイズはスタンドと壁掛けどちらの飾り方も可能です。お部屋のイメージに合わせてお使い頂けます。</li>\r\n          <li class=\"list__item\">A2、B2、B3サイズの場合は、<a href=\"/products/detail/431/\" target=\"_blank\">ポスターフレーム スタンダード スタンド専用</a>をご購入ください。</li>\r\n        </ul>\r\n      <div>\r\n    <div>\r\n    <div class=\"c-flame--xs-primary\">\r\n     <p>午前9～11時までの電話予約に限り、A2/A3/B2/B3/B4サイズの各クリアーは、在庫がある場合、翌日配送サービスに対応致します。<a href=\"/guide/next-day-delivery/\" target=\"_blank\">翌日到着のご対応について</a></p>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">スタンド形状別 商品の比較表</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <table class=\"c-table\">\r\n        <tbody>\r\n          <tr>\r\n            <th></th>\r\n            <th>ポスターフレーム スタンダード</th>\r\n            <th>ポスターフレーム スタンダード スタンド専用</th>\r\n            <th>大型ポスターフレーム スタンドタイプ</th>\r\n          </tr>\r\n          <tr>\r\n            <th nowrap>イメージ</th>\r\n            <td>\r\n              <div><a data-target=\"poster_std\" class=\"js-modal__trigger--open\"><img src=\"/storage/images/poster/poster_std/poster_std_6.jpg\"></a></div>\r\n              <div id=\"poster_std\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std/poster_std_6.jpg\" class=\"u-display--block u-margin--auto\"></div>\r\n            </td>\r\n            <td>\r\n              <div><a data-target=\"poster_std_stand\" class=\"js-modal__trigger--open\"><img src=\"/storage/images/poster/poster_std_stand/poster_std_stand_7.jpg\"></a></div>\r\n              <div id=\"poster_std_stand\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_std_stand/poster_std_stand_7.jpg\" class=\"u-display--block u-margin--auto\"></div>\r\n            </td>\r\n            <td>\r\n              <div><a data-target=\"poster_stand\" class=\"js-modal__trigger--open\"><img src=\"/storage/images/poster/poster_stand/poster_stand_10.jpg\"></a></div>\r\n              <div id=\"poster_stand\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/poster/poster_stand/poster_stand_10.jpg\" class=\"u-display--block u-margin--auto\"></div>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <th nowrap>スタンド対応サイズ</th>\r\n            <td>A3・B4サイズ</td>\r\n            <td>A2・B3・B2サイズ</td>\r\n            <td>A1・A0・B1サイズ</td>\r\n          </tr>\r\n          <tr>\r\n            <th>スタンド材質</th>\r\n            <td>金具</td>\r\n            <td>アクリル</td>\r\n            <td>アクリル</td>\r\n          </tr>\r\n          <tr>\r\n            <th>縦横兼用</th>\r\n            <td>可</td>\r\n            <td>可</td>\r\n            <td>不可</td>\r\n          </tr>\r\n          <tr>\r\n            <th>セミオーダー対応</th>\r\n            <td>可</td>\r\n            <td>不可</td>\r\n            <td>不可</td>\r\n          </tr>\r\n          <tr>\r\n            <th>製品ページ</th>\r\n            <td>-</td>\r\n            <td class=\"c-text--sm-center\"><a href=\"/products/detail/431/\" target=\"_blank\">詳細はこちら</a></td>\r\n            <td class=\"c-text--sm-center\"><a href=\"/products/detail/141/\" target=\"_blank\">詳細はこちら</a></td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-15 06:41:13','2022-05-30 07:12:08'),(6,1,'【アクリル板】キャスト規格スミペ（メーカー直送）200128','<div class=\"l-article--column-1\">\r\n    <ul class=\"c-list--note\">\r\n      <li class=\"list__item c-text--xs\">カートで表示されるサイズが実際の製品サイズとなります</li>\r\n    </ul>\r\n</div>\r\n\r\n<div class=\"l-article--column-1\" id=\"makerdirect\">\r\n  <p class=\"js-modal\">\r\n    <a class=\"js-modal__trigger--open c-label--lg-enpou\" data-target=\"tyokusou\">必読：「メーカー直送」について</a>\r\n    <div id=\"tyokusou\" class=\"c-window--md js-modal__content\">\r\n      <div class=\"l-article--column-1\">\r\n        <p><strong>「メーカー直送」について</strong></p>\r\n        <ul class=\"article__content c-list--disc\">\r\n          <li class=\"list__item\">メーカー直送品の為、代金引換はご利用頂けません。</li>\r\n          <li class=\"list__item\">貨物運送の為、配達は祝日を除く月～金曜日の昼間になり、時間指定はお受けできません。</li>\r\n          <li class=\"list__item c-text--md-danger\">1階（玄関先、エントランス）でのお渡しになります。\r\n            <ul class=\"c-list\">\r\n              <li class=\"list__item\">原則、大型トラック4t車で配達となります。(道幅等、要ご確認下さい。)</li>\r\n              <li class=\"list__item\">道幅等で4t車不可の場合、2t車でのご対応となりますが、2t車の対応外地域はチャーター便となり別途送料が掛かります。2t車配送希望の場合、事前に弊社までご確認をお願いします。</li>\r\n              <div class=\"l-article--column-2\">\r\n                    <div class=\"article__content\"><img src=\"/storage/images/share/4t_track.jpg\">\r\n                      <p class=\"c-text--sm-center\" style=\"color: #000;\">4t車イメージ</p>\r\n                    </div>\r\n                    <div class=\"article__content\"><img src=\"/storage/images/share/2t_track.jpg\">\r\n                      <p class=\"c-text--sm-center\" style=\"color: #000;\">2t車イメージ</p>\r\n                    </div>\r\n                  </div>\r\n            </ul>\r\n          </li>\r\n          <li class=\"list__item\">配達の際にお受け取りができないと再配達料が掛かる場合があります。</li>\r\n          <li class=\"list__item\">注文枚数や総重量によってはパレットを使用しての搬入となる場合があります。搬入方法についてはご指定できませんのでご了承下さい。</li>\r\n          <li class=\"list__item\">大型トラックで配達する為、お届け先の道幅が狭い場合、お届け出来ない場合があります。</li>\r\n          <li class=\"list__item\">道幅が狭く配達出来ないことが判明した場合、近隣の営業所、又はご住所近くでの引き渡しになります。 特に大板の場合、荷卸しのお手伝いをお願いする事があります。 必ず事前にお問い合わせ下さい。</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n  </p>\r\n</div>','2019-05-15 06:46:05','2020-01-28 01:11:15'),(7,6,'【ポリカーボネート板】ポリカーボネート板 フリーカット/カーポート 20200414(200609解除)','<div class=\"l-article--column-1\">\r\n  <div class=\"detail__history\">\r\n    <ul class=\"c-historyList\">\r\n      <li class=\"historyList__item\">\r\n        <time datetime=\"2020/04/14\">2020/04/14 </time>\r\n        <p class=\"item__title\">現在</p>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n  <div class=\"article__content\">\r\n    <table class=\"c-table\">\r\n      <tbody>\r\n        <tr>\r\n          <th>色調</th>\r\n          <th>板厚（mm）</th>\r\n          <th>入荷予定</th>\r\n        </tr>\r\n        <tr>\r\n          <td>クリアー（片面耐擦傷・耐候）</td>\r\n          <td>3 / 5 / 8</td>\r\n          <td>若干あり</td>\r\n        </tr>\r\n        <tr>\r\n          <td>クリアー（両面耐擦傷・耐候）</td>\r\n          <td>3 / 5 / 8</td>\r\n          <td>若干あり</td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </div>\r\n  <div class=\"article__content\">\r\n    <ul class=\"c-list--md-disc\">\r\n      <li class=\"list__item c-text--md-danger\">欠品製品はメーカー生産が追い付いておらず、記載の入荷予定通りに出荷できない場合もございます。</li>\r\n      <li class=\"list__item\">サイズによっては対応できる可能性がございます。お急ぎの場合は<a href=\"/support/contact/\" target=\"_blank\">お問い合わせ</a>ください。</li>\r\n    </ul>\r\n  </div>\r\n</div>','2019-05-15 09:37:40','2020-06-11 07:10:37'),(8,8,'【ポリカーボネート板】ポリカーボネート板/円板/階段 セミオーダー','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">出荷目安は、正式注文後、土日祭日と弊社休業日を除いた出荷までの日数目安です。</li>\r\n    <li class=\"list__item\">数がまとまる場合は日数が異なりますので、事前にお問い合わせ下さい。（万が一の場合には、予定通りに出荷出来なくなる場合があります）</li>\r\n  </ul>\r\n</div>','2019-05-15 09:38:54','2020-03-27 06:49:38'),(9,7,'【汎用】沖縄・離島のみ','<ul class=\"c-list--disc\">\r\n  <li class=\"list__item\">沖縄・離島は別途送料が必要になります。事前にお問い合わせ下さい。</li>\r\n</ul>','2019-05-15 09:39:39','2019-10-13 12:49:54'),(10,5,'【ポスターフレーム】ポスターフレームスタンダード','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">アクリルの特性上、大型サイズは多少反りやタワミが出る場合があります。</li>\r\n    <li class=\"list__item\">穴位置が合わせずらい場合は、表裏どちらかの板を反転させ組立てを行ってください。</li>\r\n    <li class=\"list__item js-modal\">本製品を壁面に設置する場合、確実にネジ等が固定できる<a data-target=\"wall_setting_1\" class=\"js-modal__trigger--open\">強度の高い壁</a><div id=\"wall_setting_1\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/share/wall_setting.jpg\" class=\"u-display--block u-margin--auto\"></div>に設置して下さい。</li>\r\n    <li class=\"list__item\">色がUVカットクリアーの場合、表面のみUVカットクリアーとなります。</li>\r\n  </ul>\r\n  <ul class=\"article__content c-list--disc\">\r\n    <h3 class=\"section__caption c-heading--sm\">複数ご注文の場合</h3>\r\n    <li class=\"list__item\">複数ご注文の場合、台数分まとめての梱包になります。（説明書は1梱包に付き１枚付属）</li>\r\n    <li class=\"c-text--note\">説明書は1梱包に付き１枚付属</li>\r\n  </ul>\r\n</div>','2019-05-16 06:30:04','2021-06-02 02:08:04'),(11,7,'【アクリル板】アクリル押出板','<ul class=\"c-list--disc\">\r\n  <li class=\"list__item\">1300x1100mm、1830x915mm、2000x1000mmは、代金引換がご利用頂けません。お届け先が個人宅の方はこのサイズはご購入頂けません。</li>\r\n  <li class=\"list__item\">1300x1100mm、1830x915mm、2000x1000mmは、お届け先が下記の場合ご購入頂けません。<br> お届けが出来ない場所：工事現場、集合住宅内の看板の出ていないオフィス</li>\r\n  <li class=\"list__item\">配達は祝日を除く月～金曜日になり、到着時間指定はお受けできません。</li>\r\n  <li class=\"list__item\">配送日はメールにてご連絡致しますので、必ずご確認願います。</li>\r\n  <li class=\"list__item\">運送会社の都合により、1階でのお渡しになる場合がございます。</li>\r\n  <li class=\"list__item\">配達の際にお受け取りができないと再配達料が掛かる場合があります</li>\r\n  <li class=\"list__item\">大型トラックで配達する為、お届け先の道幅が狭い場合、お届け出来ない場合があります。</li>\r\n  <li class=\"list__item\">道幅が狭く配達出来ないことが判明した場合、近隣の営業所、又はご住所近くでの引き渡しになります。特に大板の場合、荷卸しのお手伝いをお願いする事があります。 必ず事前にお問い合わせ下さい。</li>\r\n</ul>','2019-05-20 07:22:48','2020-01-24 08:52:48'),(12,2,'【アクリル板】アクリル押出板_bkup','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"section__title c-heading--lg-border\">製品特長</h2>\r\n    <h3 class=\"section__caption c-heading--sm\">アクリル押出板 （キャスト板との比較）</h3>\r\n    <div class=\"l-article--column-1\">\r\n    <div class=\"article__content\"><img src=\"/storage/images/acrylic/teijakuzai/oshidashizai.gif\"></div>\r\n      <table class=\"c-table\">\r\n        <tbody>\r\n          <tr>\r\n            <th class=\"c-text--md\">押し出し材</th>\r\n            <td>\r\n              <p class=\"c-text--md\">粘土状になっているアクリル樹脂をローラーから押し出して作る製法</p>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <th class=\"c-text--md\">長所</th>\r\n            <td>\r\n              <p class=\"c-text--md\">１．板厚の寸法精度に優れる</p>\r\n              <p class=\"c-text--md\">２．接着性に優れている。溶剤接着（溶かして接着する方法）に向く</p>\r\n              <p class=\"c-text--md\">３．熱曲げ加工しやすい</P>\r\n              <p class=\"c-text--md\">４．安価である</P>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <th class=\"c-text--md\">短所</th>\r\n            <td>\r\n              <p class=\"c-text--md\">１．温度や環境の影響により、反りが出やすい</p>\r\n              <p class=\"c-text--md\">２．溶液や薬品でクラック（ヒビ）が入り易い</p>\r\n              <p class=\"c-text--md\">３．高速切削加工に向かない（過熱部分が融けるため）</P>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">押出板について</h2>\r\n    <h3 class=\"c-heading--sm\">アクリル押出板　規格サイズ</h3>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"c-list--disc\">\r\n        <li class=\"list__item\">450x300mm、600x450mm、910x450mmの板サイズの寸法公差は±0.8mmです。</li>\r\n        <li class=\"list__item\">1300x1100mm、1830x915mm、2000x1000mmのアクリル押出板サイズは、縦横共に長め（＋1～100mm程度）になっています。</li>\r\n        <li class=\"list__item\">2000x1000mm以上の大板サイズをご希望の場合は<a href=\"/products/detail/106/\" target=\"_blank\">アクリルキャスト板 フリーカット </a>をご利用下さい。</li>\r\n        <li class=\"list__item\">アクリル板の端面はカットのみ（仕上げ無し）。 \r\n          <a data-target=\"zumen_0\" class=\"js-modal__trigger--open\">断面写真はこちら 。</a>\r\n          <div id=\"zumen_0\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/acrylic/teijakuzai/teijakuzai_1.jpg\" class=\"u-display--block u-margin--auto\"></div>\r\n        </li>\r\n      </ul>\r\n    </div>\r\n    <h3 class=\"c-heading--sm u-margin\">アクリル押出板のカラー（色）</h3>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"c-list--disc\">\r\n        <li class=\"list__item\">厚みによって色味が若干異なる場合があります。</li>\r\n        <li class=\"list__item\">アクリルミラーは反りが目立ちます。 <a href=\"/products/detail/111/\" target=\"_blank\">アクリルミラー使用上のご注意</a> 参照。</li>\r\n      </ul>\r\n    </div>\r\n    <h3 class=\"c-heading--sm u-margin\">アクリル押出板の厚さ</h3>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"c-list--disc\">\r\n        <li class=\"list__item\">厚さは2～10mm。色によって取り扱いの厚みが異なります。13、15mm厚は<a href=\"/products/detail/283/\" target=\"_blank\">アクリル板加工 セミオーダー</a>をご利用下さい。</li>\r\n        <li class=\"list__item\">アクリル板の板厚公差は、厚みによって異なります。 <a href=\"/material/weight/#02\" target=\"_blank\">アクリル板の板厚許容公差</a> 参照。</li>\r\n      </ul>\r\n    </div>\r\n    <h3 class=\"c-heading--sm u-margin\">アクリル押出板のご注意</h3>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"c-list--disc\">\r\n        <li class=\"list__item\">サイズ変更・端面仕上・穴開け加工等をご希望の場合は<a href=\"/products/detail/283/\" target=\"_blank\">アクリル板加工 セミオーダー</a>をご利用下さい。</li>\r\n        <li class=\"list__item\">温度や環境の影響により、アクリル押出板が反る場合があります。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-20 07:47:41','2023-09-14 02:59:05'),(15,4,'【リビングプラス】ドロップレット・インセンスホルダー','<section class=\"article__content\">\r\n  <h3 class=\"section__caption c-heading--sm\">ドロップレット・インセンスホルダー（droplet incense holder）</h3>\r\n    <table class=\"c-table--sm u-width--70\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--30\">サイズ</th>\r\n        <td>Φ54×17mm（厚み）</td>\r\n      </tr>\r\n      <tr>\r\n        <th>重量</th>\r\n        <td>約150g</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n  <div class=\"js-modal c-text--left u-margin--top-8\"><a data-target=\"zumen_0\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n    <div id=\"zumen_0\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/livingplus/droplet_incense/droplet_incense_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n  </div>\r\n</section>','2019-05-21 00:52:10','2019-12-11 09:58:39'),(16,2,'【リビングプラス】ドロップレット・インセンスホルダー','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <div class=\"article__content\">\r\n        <ul class=\"article__content c-list--disc\">\r\n          <li class=\"list__item\">ステンレス材を切削加工して製作したお香立てです。</li>\r\n          <li class=\"list__item\">上面は湾曲しており灰の受け皿になっています。また、ご使用にならない時は逆さまにしてペーパーウェィトとしてお使いいただくことが可能です。</li>\r\n          <li class=\"list__item\">様々な外径のお香をしっかりホールドする為に、お香立ての孔部分には高精度な切削加工が施されています。</li>\r\n          <li class=\"list__item\">ポリッシュ/ブラスト仕上げの二種類からお選びいただけます。</li>\r\n        </ul>\r\n      </div>\r\n    </div>\r\n    <h2 class=\"c-heading--lg-border\">2種類の仕上げをご用意</h2>\r\n    <div class=\"l-article--column-3\">\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/droplet_incense/droplet_incense_4.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">ブラスト</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/droplet_incense/droplet_incense_5.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">ポリッシュ</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-21 01:47:53','2019-12-21 05:08:47'),(17,5,'【リビングプラス】ドロップレット・インセンスホルダー','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">傷がつきやすい製品である為、お手入れの際にはタワシ等は用いず、中性洗剤を含ませた金属用のセーム布等（不織布）をお使いください。</li>\r\n    <li class=\"list__item\">水平な安定した台の上に置いてお使い下さい。</li>\r\n    <li class=\"list__item\">傷が目立つ様になったら、市販の金属用磨き布・研磨剤（鏡面用）で磨いてください。</li>\r\n    <li class=\"list__item\">クレンザー等の粗めの研磨剤の使用はお控えください。</li>\r\n    <li class=\"list__item\">お香が孔の内部で折れてしまった場合は、画鋲やピンを孔に挿し込んでから中のお香を取り出してください。</li>\r\n  </ui>\r\n</div>','2019-05-21 02:13:31','2019-06-13 04:18:40'),(19,2,'【工具・用品】オルファ アクリルカッター','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <p>厚さ5mm程度（カット距離が長い場合は3mm程度）までのアクリル板の直線切りに使用可能。すじ入れや面取りにも使用できます。</p>\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">アクリル・ポリカーボネートなどのプラスチック板専用の作業用カッター。</li>\r\n        <li class=\"list__item\">アクリルの対象板厚は5mmまで。</li>\r\n        <li class=\"list__item\">刃はスライド式で、本体に収納でき安全に保管できます。</li>\r\n        <li class=\"list__item\">替刃2枚付属。</li>\r\n      </ul>\r\n    </div>\r\n    <h2 class=\"c-heading--lg-border\">選べる2種類のサイズ</h2>\r\n    <div class=\"l-article--column-3\">\r\n      <div class=\"article__content\"><img src=\"/storage/images/item/olfa_cutter/olfa_cutter_s_1.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">S</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/item/olfa_cutter/olfa_cutter_l_1.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">L</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/item/olfa_cutter/olfa-cutter600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>カットしたい部分を正確に計測して、アクリル板の保護紙に鉛筆等でカットする線を描きます（保護紙がない場合は、マスキングテープなどを貼ってガイド線を描くと良いでしょう）。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/item/olfa_cutter/olfa-cutter600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>描いた線に金属製の定規を合わせ、しっかりと押さえます。カッターの尖った部分を板に当て、定規に沿ってかき切るよう溝を入れていきます（写真はオルファアクリルカッターP800を使用）。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">板の両面から切り込みを入れると、お互いの切り込みがずれるので、片面側からのみ溝を入れてください。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/item/olfa_cutter/olfa-cutter600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>アクリルカッターで繰り返し切り込みを入れ、板厚の3分の1程度に均等な溝が入った所で、机の角等にアクリル板の溝の裏面を当ててしっかりと持ちます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/item/olfa_cutter/olfa-cutter600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>下方向に力を入れて、板を折り割ります。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">折り割る時に、アクリル板の角で怪我をしないように充分気をつけてください。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/item/olfa_cutter/olfa-cutter600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>折り割った切断面は尖っている部分（特に両角）がありますので、必要に応じてヤスリ等で端面処理をしてください。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">金ヤスリで尖った部分を落としてから、サンドペーパーで平らに仕上げると、端面が綺麗になります。また、アクリル板の角は鋭利なので、手で触れる所は必ず面取りをするようお勧めします。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <p class=\"section__item c-text--right\"><a href=\"/blog/product/348/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>使用レポートはこちら</a></p>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>適用<p><a href=\"/blog/diy/284/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>使用レポート</a></p></td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-21 03:15:29','2019-12-23 06:29:31'),(20,5,'【工具・用品】刃物','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">刃物ですので取扱いには十分ご注意下さい。</li>\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</div>','2019-05-21 08:45:04','2019-06-05 01:43:36'),(22,2,'【リビングプラス】アクリル ペントレイ','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">重合法で製作した色付きアクリル板を切削加工して製作したデスクオーガナイザー・ペントレイ。</li>\r\n        <li class=\"list__item\">散らかってしまうデスクの上を整理整頓したり、ショップやエキシビションのレセプションにお使い頂けます。</li>\r\n        <li class=\"list__item\">サイズは3種類・クリアを含む美しい発色の6色の中からお選び頂けます。色やサイズの組み合わせでデスクの上がカラーパレットの様に華やぎます。</li>\r\n      </ul>\r\n    </div>\r\n    <h2 class=\"c-heading--lg-border\">6種のカラーバリエーション</h2>\r\n    <div class=\"l-article--column-3\">\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_5.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">クリア</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_6.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">ロゼ</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_7.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">ターコイズ</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_8.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">シトロン</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_9.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">ワインレッド</p>\r\n      </div>\r\n      <div class=\"article__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_10.jpg\" class=\"js-modal--image\">\r\n        <p class=\"c-text--sm-center\">インディゴ</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-22 04:11:10','2020-02-28 01:30:56'),(23,4,'【リビングプラス】アクリル ペントレイ','<section class=\"article__content\">\r\n    <table class=\"c-table--sm u-width--70\">\r\n    <thead>\r\n      <tr>\r\n        <th>タイプ</th>\r\n        <th>溝数</th>\r\n        <th>サイズ</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <th>シングル</th>\r\n        <td>1</td>\r\n        <td>W18×L165×H15mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>ダブル</th>\r\n        <td>2</td>\r\n        <td>W33×L165×H15mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>トリプル</th>\r\n        <td>3</td>\r\n        <td>W48×L165×H15mm</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n  <div class=\"js-modal c-text--left u-margin--top-8\"><a data-target=\"zumen_0\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n    <div id=\"zumen_0\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/livingplus/desk_organizer/desk_organizer_zumen.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n  </div>\r\n</section>','2019-05-22 04:56:53','2020-02-28 01:31:02'),(25,3,'【リビングプラス】アクリル ペントレイ','<div class=\"c-cardGroup--4\">\r\n  <a href=\"/case_study/a-910202/asami.htm\" target=\"_blank\" class=\"c-card--case\">\r\n  <article>\r\n    <div class=\"card__head\">\r\n      <div class=\"card__image_cs\"><img src=\"/storage/images/example/a_910202/asami/asami510-1.jpg\"></div>\r\n    </div>\r\n    <div class=\"card__body\">\r\n      <p class=\"card__category c-text--xs\">リビングプラス</p>\r\n      <p class=\"card__title c-heading--xs\">アクリル ペントレイ</p>\r\n      <p class=\"card__user c-text--xs\">asami さま</p>\r\n    </div>\r\n  </article></a>\r\n</div>','2019-05-22 05:59:55','2020-02-28 01:31:06'),(26,2,'【ペット】バードケージ（鳥かご）ケース','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">ヒーターの温かさがケージ全体を包みます</h3>\r\n      <p class=\"article__content c-text--md\">ヒーターの熱が逃げ難くなりケージ全体が温まるので、鳥さんの活動量も上がります。透明なので、鳥さんの様子を見ながら保温できます。</p>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">市販ケージにピッタリサイズ</h3>\r\n      <p class=\"article__content c-text--md\">流通量が多い市販ケージサイズに合う既製サイズを準備。 インコや文鳥などに利用されているケージにペットヒーターを設置して最適なサイズです。</p>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">手入れが簡単なシンプル構造</h3>\r\n      <p class=\"article__content c-text--md\">鳥さんの健康とオールシーズンで使用できるよう配慮した、前面解放タイプ。 汚れが周りに飛び散らず、ケースの底に新聞紙がそのまま敷けるので、掃除も簡単に行えます。</p>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">鳥さんのやけどを防ぐヒーターのケースマウント</h3>\r\n      <p class=\"article__content c-text--md\">ヒーターは、鳥さんがヒーターで火傷してしまったり、 コードで感電しないよう、ケース側に 設置できます。ヒーターは利用者が多いアサヒ・ペットヒーター60Wを設置できる構造です。</p>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"section__caption c-heading--sm\">規格サイズのケースが合わない方に</h3>\r\n      <ul class=\"c-list--disc\">\r\n        <li >ピッタリの規格サイズが無い時は、「<a href=\"/products/detail/332/\" target=\"_blank\">セミオーダー品</a>」が便利です。ヒーターやサーモスタット用の穴開けも個別に指定できます。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">こだわりの設計</h2>\r\n    <div class=\"l-article--column-2-center\">\r\n      <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case/bird_cage_case_2.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w60\">\r\n        <h3 class=\"c-heading--sm\">ケース側にヒーター設置が可能</h3>\r\n        <p class=\"c-text--md\">ケース側面にヒーター設置穴があり、内側からヒーターを掛けて利用できます。鳥さんの好みに合わせ、左右どちら向きでも取付できます。</p>\r\n        <p class=\"c-text--note\">バードケージケース500/21/470(R・L)は片側専用となります。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-2-center\">\r\n      <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case/bird_cage_case_3.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w60\">\r\n        <h3 class=\"c-heading--sm\">メンテナンスも簡単</h3>\r\n        <p class=\"c-text--md\">ケースの底は、新聞紙がピッタリ入るサイズになっています。新聞紙を複数枚重ねて敷いておき、汚れたら1枚ずつ外して行けるので、掃除も簡単。「コンパニオンバード誌」ならではのアイディアです。</p>\r\n        <p class=\"c-text--note\">バードケージケース600</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">コンパニオンバード誌からのアドバイス</h2>\r\n    <div class=\"l-article--column-2-center\">\r\n      <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case/bird_cage_case_4.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w60\">\r\n        <h3 class=\"c-heading--sm\">鳥さんを定期的に休ませよう</h3>\r\n        <p class=\"c-text--md\">夜は布をかぶせて休ませましょう。 保温器具を使用する場合は、暑くなり過ぎることがありますので、温度計を設置したり、サーモスタットを使用しましょう。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-2-center\">\r\n      <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case/bird_cage_case_5.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w60\">\r\n        <h3 class=\"c-heading--sm\">夏の暑さ対策をしよう</h3>\r\n        <p class=\"c-text--md\">夏は水を入れて凍らせたペットボトルを緩衝材（プチプチ）で包み、 ケース内に設置すると、程よい涼しさが長持ちします。室温が高くなったらエアコンを併用しましょう。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-2-center\">\r\n      <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case/bird_cage_case_6.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w60\">\r\n        <h3 class=\"c-heading--sm\">何で扉が無いの？</h3>\r\n        <p class=\"c-text--md\">それは、扉で完全に密閉してしまうと、鳥さんの脂粉やフケなどが ケース内に籠ってしまい、鳥さんの病気を引き起こす原因になるためです。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"c-flame--sm-gray\">\r\n      <div class=\"l-article--column-2-center\">\r\n        <div class=\"article__content--w20\"><img src=\"/storage/images/animal/bird_cage_case/cb18-head499.jpg\" class=\"js-modal--image\"></div>\r\n        <div class=\"article__content--w80\">\r\n          <h4 class=\"c-heading--xs\">コンパニオンバード誌とは</h4>\r\n          <p class=\"c-text--sm\">インコを中心とした鳥さんの専門誌。専門家や鳥さんと暮らしている編集者さんによるオリジナルの提案が好評で、飼い主さんには絶大な人気の専門誌です。2012年12月発売号で本製品が紹介されています。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-22 08:00:09','2020-07-01 05:13:48'),(27,2,'【部品・装飾品】バンポン','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">半球状透明の滑り止め。 ケースや板の底に付けてキズ防止に使用できます。 </li>\r\n        <li class=\"list__item\">Ｓサイズ：10個入、Ｌサイズ：6個入。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon/bumpon600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>箱型ケースや台などのすべり留めにバンポンを準備します。サイズはＳとＬの2種類があります（写真はＳサイズ）。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon/bumpon600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>バンポンを貼る位置を綺麗にして、バンポンを台紙から剥がし、希望する場所に置きます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">貼る場所の表面が汚れたままだとバンポンが剥がれやすくなりますので、油分等をしっかり拭き取ります。<a href=\"/products/detail/242/\" target=\"_blank\">ウェルシーＡ</a>を使うと効果的。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon/bumpon600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>しっかり貼り付くように強く押さえます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon/bumpon600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>必要な個所にバンポンを貼り付けて作業終了です。</p>\r\n      </div>\r\n    </div>\r\n    \r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>適用</td>\r\n            <td>適用</td>\r\n            <td>適用</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 00:10:09','2019-07-18 04:24:15'),(28,4,'【部品・装飾品】バンポン','<div class=\"l-article--column-1\">\r\n  <h3 class=\"section__caption c-heading--sm\">バンポン</h3>\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">ポリウレタン製（透明）</li>\r\n    <li class=\"list__item\">表示寸法は多少の誤差がございます。</li>\r\n  </ul>\r\n  <table class=\"c-table--sm u-width--70\">\r\n    <thead>\r\n      <tr>\r\n        <th class = \"u-width--40\"></th>\r\n        <th>直径</th>\r\n        <th>高さ</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <th>Sサイズ</th>\r\n        <td>7.9mm</td>\r\n        <td>2.2mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>Lサイズ</th>\r\n        <td>11.2mm</td>\r\n        <td>5.1mm</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 00:39:04','2019-06-22 04:24:03'),(29,5,'【部品・装飾品】バンポン全種','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">屋内外を問わず紫外線や熱の影響で黄ばむことがあります。</li>\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</div>','2019-05-23 00:42:57','2019-06-05 01:52:35'),(30,4,'【部品・装飾品】平型バンポン','<h3 class=\"section__caption c-heading--sm\">平型バンポン</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-width--80\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\" nowrap>シートサイズ</th>\r\n        <td>115mm×50mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>直径</th>\r\n        <td>20mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>厚み</th>\r\n        <td>0.8mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>色</th>\r\n        <td>透明</td>\r\n      </tr>\r\n      <tr>\r\n        <th>基材</th>\r\n        <td>ポリウレタン</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 02:23:21','2019-12-12 05:00:52'),(31,2,'【部品・装飾品】平型バンポン','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">平型円形の滑り止め。高い摩擦性と優れた弾性、及び振動抑制効果があります。</li>\r\n        <li class=\"list__item\">ケースや板の底に貼り付けてキズ防止として使用可能。1シート10個付き。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon-flat/bumpon-flat600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>箱型ケースやコの字ディスプレイ台などの滑り止めに、平型バンポンを準備します。粘着剤部分に指の指紋や埃がつくと粘着力が弱くなるので、バンポンを剥がす時には指紋や埃が付着しないように注意しましょう。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">台紙から剥がす時に、バンポンの端（または両端）を挟むように剥がすと、指紋が付着し辛くなります。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon-flat/bumpon-flat600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>バンポンを貼る場所を綺麗にします。バンポンを台紙から剥がし、希望する場所に軽く乗せます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">貼る場所の表面が汚れたままだとバンポンが剥がれやすくなりますので、油分等をしっかり拭き取ります。<a href=\"/products/detail/242/\" target=\"_blank\">ウェルシーＡ</a>を使うと効果的。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon-flat/bumpon-flat600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>空気が入らないように上から強く押さえ、しっかりと貼り付けます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon-flat/bumpon-flat600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>必要な場所に貼り付けて作業終了です。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">バンポンは0.8mm厚の薄さですが、ケースの底面に貼る場合はがたつきを抑える為に、最低でも4カ所に貼り付ける事をお勧めします。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <p class=\"section__item c-text--right\"><a href=\"/blog/product/221/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>使用レポートはこちら</a></p>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>適用</td>\r\n            <td>適用</td>\r\n            <td>適用</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 02:26:10','2019-10-15 05:54:03'),(32,4,'【ペット】バードケージ（鳥かご）ケース','<div class=\"l-article--column-1\">\r\n  <section class=\"article__content\">\r\n    <h3 class=\"section__caption c-heading--sm\">共通仕様</h3>\r\n    <table class=\"c-table--sm u-width--70\">\r\n      <thead>\r\n        <tr>\r\n          <th>素材</th>\r\n          <td>アクリル</td>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n      <tr>\r\n        <th>板厚</th>\r\n        <td>5mm（背板のみ3mm）</td>\r\n      </tr>\r\n      </tbody>\r\n    </table>\r\n  </section>\r\n\r\n  <section class=\"article__content u-margin--top-32\">\r\n    <h3 class=\"section__caption c-heading--sm\">タイプ別仕様</h3>\r\n    <table class=\"c-table--sm u-whitespace--nowrap\">\r\n      <thead>\r\n        <tr>\r\n          <th></th>\r\n          <th>外寸法</th>\r\n          <th>内寸法</th>\r\n          <th>対象ケージ</th>\r\n          <th>重量</th>\r\n          <th>図面</th>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n        <tr>\r\n          <th>470</th>\r\n          <td>W470ｘD320ｘH430mm</td>\r\n          <td>W460ｘD317ｘH420mm</td>\r\n          <td>W325ｘD270ｘH400mm以下</td>\r\n          <td>約4.1kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"470\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"470\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case/birdcage-case-zumen470.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n        <tr>\r\n          <th>21</th>\r\n          <td>W420ｘD420ｘH435mm</td>\r\n          <td>W410ｘD417ｘH425mm</td>\r\n          <td>HOEI21手のり</td>\r\n          <td>約4.8kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"21\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"21\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case/birdcage-case-zumen21.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n        <tr>\r\n          <th>500</th>\r\n          <td>W500ｘD470ｘH590mm</td>\r\n          <td>W490ｘD467ｘH580mm</td>\r\n          <td>HOEI35手のり</td>\r\n          <td>約7.1kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"500\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"500\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case/birdcage-case-zumen500.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n        <tr>\r\n          <th>600</th>\r\n          <td>W610ｘD553ｘH635mm</td>\r\n          <td>W600ｘD550ｘH625mm</td>\r\n          <td>HOEI465オカメ</td>\r\n          <td>約10kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"600\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"600\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case/birdcage-case-zumen600.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </section>\r\n  <section class=\"article__content\">\r\n    <p class=\"c-text--left\"><a href=\"/storage/images/animal/bird_cage_case/bird-cage-case-handling-manual.pdf\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>取扱説明書</a>\r\n  </section>\r\n</div>\r\n<section class=\"article__content\">\r\n  <h3 class=\"section__caption c-heading--sm\">ご希望サイズが無い場合</h3>\r\n  <div class=\"l-article--column-1\">\r\n    <ul class=\"article__content c-list--disc\">\r\n      <li class=\"list__item\">ご希望のサイズが無い場合は<a href=\"/products/detail/332/\" target=\"_blank\">セミオーダー</a>をご利用下さい。</li>\r\n    </ul>\r\n  </div>\r\n</section>','2019-05-23 02:46:04','2019-12-06 04:35:16'),(33,2,'【部品・装飾品】角型バンポン','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">素材の厚みに合わせた平型長方形の滑り止め。</li>\r\n        <li class=\"list__item\">アクリル板の端面やケースの底に貼り付けて、滑り防止やキズ防止に最適。</li>\r\n        <li class=\"list__item\">小さいサイズながら高い摩擦性と弾性に優れます。サイズは4種類。 </li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon_rectangle/bumpon_rectangle600_01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>箱型ケースやコの字ディスプレイ台などの滑り止めに、角型バンポンを準備します。粘着剤部分に指の指紋や埃がつくと粘着力が弱くなるので、バンポンを剥がす時には指紋や埃が付着しないように注意しましょう。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">台紙から剥がす時に、バンポンの端（または両端）を挟むように剥がすと、指紋が付着し辛くなります。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon_rectangle/bumpon_rectangle600_02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>バンポンを貼る場所を綺麗にします。バンポンを台紙から剥がし、希望する場所に軽く乗せます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">貼る場所の表面が汚れたままだとバンポンが剥がれやすくなりますので、油分等をしっかり拭き取ります。<a href=\"/products/detail/242/\" target=\"_blank\">ウェルシーＡ</a>を使うと効果的。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon_rectangle/bumpon_rectangle600_03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>空気が入らないように上から強く押さえ、しっかりと貼り付けます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/bumpon_rectangle/bumpon_rectangle600_04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>必要な場所に貼り付けて作業終了です。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">バンポンは0.8mm厚の薄さですが、ケースの底面に貼る場合はがたつきを抑える為に、最低でも4カ所に貼り付ける事をお勧めします。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <p class=\"section__item c-text--right\"><a href=\"/blog/product/491/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>使用レポートはこちら</a></p>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>適用</td>\r\n            <td>適用</td>\r\n            <td>適用</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 02:59:02','2019-10-15 05:57:32'),(34,4,'【部品・装飾品】角型バンポン','<h3 class=\"section__caption c-heading--sm\">角型バンポン（透明角型滑り止め）</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-whitespace--nowrap\">\r\n    <thead>\r\n      <tr>\r\n        <th></th>\r\n        <th>サイズ</th>\r\n        <th>厚み</th>\r\n        <th>色</th>\r\n        <th>基材</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <th>3mm幅x10個付</th>\r\n        <td>20mm×30mm</td>\r\n        <td>0.8mm</td>\r\n        <td>透明</td>\r\n        <td>ポリウレタン</td>\r\n      </tr>\r\n      <tr>\r\n        <th>5mm幅x8個付</th>\r\n        <td>20mm×40mm</td>\r\n        <td>0.8mm</td>\r\n        <td>透明</td>\r\n        <td>ポリウレタン</td>\r\n      </tr>\r\n      <tr>\r\n        <th>10mm幅x5個付</th>\r\n        <td>20mm×50mm</td>\r\n        <td>0.8mm</td>\r\n        <td>透明</td>\r\n        <td>ポリウレタン</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 03:02:59','2021-03-19 02:38:08'),(35,4,'【部品・装飾品】オリジナル透明蝶番','<h3 class=\"section__caption c-heading--sm\">オリジナル透明蝶番（3個）</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-whitespace--nowrap\">\r\n    <thead>\r\n      <tr>\r\n        <th></th>\r\n        <th>寸法</th>\r\n        <th>厚み</th>\r\n        <th>蝶番結合部厚み</th>\r\n        <th>素材</th>\r\n        <th>芯</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <th>Mサイズ</th>\r\n        <td>約35x30mm(3個入り)</td>\r\n        <td>約1.5mm</td>\r\n        <td>約4mm</td>\r\n        <td>ABS樹脂</td>\r\n        <td>鉄芯</td>\r\n      </tr>\r\n      <tr>\r\n        <th>LLサイズ</th>\r\n        <td>約50x35mm(3個入り)</td>\r\n        <td>約1.5mm</td>\r\n        <td>約4mm</td>\r\n        <td>ABS樹脂</td>\r\n        <td>鉄芯</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 04:12:13','2024-10-24 04:15:13'),(36,5,'【部品・装飾品】数量割引なしのみ','<section class=\"p-notes c-section\">\r\n  <ul class=\"c-list--disc\">\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</section>','2019-05-23 04:13:50','2019-05-23 05:02:03'),(37,2,'【部品・装飾品】オリジナル透明蝶番','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">アクリルケースの開閉扉に使用した時、目立たない透明蝶番。</li>\r\n        <li class=\"list__item\">アクリサンデー接着剤で取付可能。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-clear/clearhinge600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>蝶番を取付る位置を計ります。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">幅の広い板などに使用する場合は、複数の蝶番を使用します。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-clear/clearhinge600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p> 蝶番を指で固定し、外側を少し浮かせます。浮かせた場所から注入器の針を奥に刺し込んで、接着剤を適量流し込みます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">透明蝶番のヒンジ部分に接着剤が流れ込まないように、慎重に接着してください。奥から手前に引きながら溶剤を流し込むと、接着面全体に溶剤が綺麗に流れ込みます。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-clear/clearhinge600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>溶剤を流し込んだ後、蝶番の接着面に入った空気を押し出すように指で軽く押さえます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">接着面を抑え過ぎると溶剤が外側に漏れてしまうので、様子を見ながら作業をしてください。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-clear/clearhinge600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>接着剤が乾いたら、反対側の板にも蝶番を取り付けます。蝶番を浮かせた状態で、溶剤を流し込みます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-clear/clearhinge600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>溶剤を流し込んだ後、蝶番の接着面に入った空気を押し出すように指で軽く押さえます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-clear/clearhinge600-06.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>30分程度動かさないように放置して、完全に乾いたら完成です。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">荷重の掛かる場所への使用には適しません。複数の蝶番を使用する場合は、必ず平行になるよう正確に取り付けます。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n            <th>PET板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>〇<sup>※</sup></td>\r\n            <td>〇<sup>※</sup></td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n      <ul class=\"article__content c-list--note\">\r\n        <li class=\"list__item\">接着は可能ですが、溶剤が流れにくく気泡が入りやすいです。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 04:16:19','2022-10-14 03:12:14'),(38,2,'【部品・装飾品】ステンレス蝶番','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">強度のあるステンレス蝶番。</li>\r\n        <li class=\"list__item\">使用するアクリル板が大きな場合や強度が必要な場所に使用します。</li>\r\n        <li class=\"list__item\">トラスネジで簡単に取り付け可能。対象板厚3mmまで。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge_stainless/stainlesshinge600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>アクリル板に蝶番を合わせて、取り付ける位置を決めます。2枚の板に印をつけて、穴開け加工をします。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">穴開け加工の詳細は<a href=\"/products/detail/227/\" target=\"_blank\">こちら</a>。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge_stainless/stainlesshinge600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>保護紙を剥がし、穴が綺麗に開いているか確認します。加工した板の穴にステンレス蝶番を合わせ、トラスネジを差し込みます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge_stainless/stainlesshinge600-03_2.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>板を裏返し、ナットで締めます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge_stainless/stainlesshinge600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>2ヶ所同様にネジで固定します。プラスドライバーを使用して、トラスネジが緩まない程度に締めます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">トラスネジを締めすぎるとアクリル板が割れてしまう可能性がありますので、注意しましょう。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge_stainless/stainlesshinge600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>もう１枚の板も同様に蝶番を固定して、作業完了です。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>適用</td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    <div>\r\n  </section>\r\n</div>','2019-05-23 04:48:30','2019-07-18 04:35:46'),(39,5,'【部品・装飾品】ステンレス蝶番','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</div>','2019-05-23 04:50:34','2020-02-21 02:54:56'),(40,4,'【部品・装飾品】ステンレス蝶番','<h3 class=\"section__caption c-heading--sm\">ステンレス蝶番（２個）</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-width--70\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\">サイズ</th>\r\n        <td>32mmx23mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>蝶番</th>\r\n        <td>2個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M3トラスネジ（長さ8mm）</th>\r\n        <td>8個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M3袋ナット</th>\r\n        <td>8個</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 04:53:58','2019-06-22 04:31:18'),(41,4,'【部品・装飾品】ガラス蝶番','<h3 class=\"section__caption c-heading--sm\">ガラス蝶番</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-width--80\">\r\n    <tbody>\r\n      <tr>\r\n        <th class=\"u-width--50\" nowrap>蝶番（鋼製、クロームメッキ）</th>\r\n        <td>2個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>飾りネジ（丸型）</th>\r\n        <td>2個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>付属ネジ</th>\r\n        <td>2個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>塩化ビニールワッシャー</th>\r\n        <td>4個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M4トラスネジ（長さ12mm）</th>\r\n        <td>6個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M4ワッシャー</th>\r\n        <td>6個</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M4ナット</th>\r\n        <td>6個</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 04:58:22','2019-12-12 05:21:27'),(42,2,'【部品・装飾品】ガラス蝶番','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">デザイン性に優れたガラス蝶番。</li>\r\n        <li class=\"list__item\">ガラス扉用の蝶番ですが、アクリル扉にも使用できます。</li>\r\n        <li class=\"list__item\">強度が必要な場所にも最適。対応板厚5mmまで。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ガラス蝶番を取り付ける位置を決め、穴開け加工をします。中心の穴は端面から10.2mmの距離、両サイドの穴は端面から13.2mmの距離になります。実際に蝶番を板に合わせて確認をしてから、穴を開けましょう。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">穴開け加工の詳細は<a href=\"/products/detail/227/\" target=\"_blank\">こちら</a>。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ガラス蝶番を板に合わせて、トラスネジを差し込みます（トラスネジの頭が外側に来るようにします）。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ワッシャーを入れ、ナットで軽く締めて仮止めします。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>同様に3ヶ所を固定して、蝶番の位置を調整した後にナットを締め込みます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">ナットを締めすぎるとアクリル板が割れてしまう可能性がありますので、注意しましょう。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>扉側の板に飾りネジ用の直径7mmの穴を開けます。板の端面からの距離は、板厚2～3mmの場合19.5mm、板厚5mmの場合は18.5mmになります。実際に蝶番を板に合わせて確認をしてから、穴加工をしましょう。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">穴開け加工の詳細は<a href=\"/products/detail/227/\" target=\"_blank\">こちら</a>。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-06.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>塩ビワッシャーを間に挟めて、ガラス蝶番の飾りネジを差し込みます（板が薄い場合は、ワッシャーを2枚使用します）。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-07.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>飾りネジをネジで固定して、作業終了です。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/hinge-glass/glasshinge600-08.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ガラス蝶番の飾りネジは一点止めなので、少なくとも2個使用して固定しましょう。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>適用</td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 05:04:16','2019-07-18 04:36:02'),(43,4,'【部品・装飾品】マグネット＆アクリルツマミ','<h3 class=\"section__caption c-heading--sm\">マグネット＆アクリルツマミ</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-width--80\">\r\n    <tbody>\r\n      <tr>\r\n        <th class=\"u-width--35\">マグネット</th>\r\n        <td>10mm角×長さ15mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>ツマミ</th>\r\n        <td>直径15mm×長さ20mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M4サラネジ</th>\r\n        <td>長さ12mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>入数</th>\r\n        <td>マグネット×1個・ツマミ×1個</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 05:48:39','2019-12-12 05:24:06'),(44,2,'【部品・装飾品】マグネット＆アクリルツマミ','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">小さくても強力なネオジム磁石をアクリルにネジ固定したマグネットと、ネジで固定する透明アクリルツマミのセット。</li>\r\n        <li class=\"list__item\">両方共に透明素材の為、取り付け時に目立ちません。</li>\r\n        <li class=\"list__item\">マグネット（アクリル部分）はアクリサンデー接着剤で簡単に接着可能。</li>\r\n        <li class=\"list__item\">付属のサラネジは板厚5ｍｍまで対応します。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <ul class=\"c-list--note\">\r\n        <li class=\"list__item\">使用方法の写真は全て旧製品になります。現行製品はマグネットをネジで固定したタイプになります。</li>\r\n      </ul>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami_magnet/magnet600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>アクリルマグネットを取り付ける位置を決めます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami_magnet/magnet600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>マグネットの手前側を少し浮かせた状態で固定し、注入器の針を刺し込んで接着剤を流し込みます。マグネットの接着面に入った空気を押し出すように指で軽く押します。接着剤が乾くまで、30分程度動かさないように放置しましょう。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">強く押さえたり位置をずらしたりすると、接着面が汚くなってしまうので、注意しましょう。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami_magnet/magnet600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>扉側に開けたサラザグリ穴に皿ネジを差し込みます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">穴開け加工の詳細は<a href=\"/products/detail/227/\" target=\"_blank\">こちら</a>。直径4～4.5mmの下穴を開けた後に、皿ネジの頭が沈む程度に、面取りドリルで面を取ります。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami_magnet/magnet600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>アクリルツマミを固定して作業終了です。ツマミのネジ穴が潰れない程度に軽く締めます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami_magnet/magnet600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>蝶番付の扉や取外しができる扉のツマミなど、様々な用途に使用してみましょう。</p>\r\n      </div>\r\n    </div>\r\n    <p class=\"section__item c-text--right\"><a href=\"/blog/product/210/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>使用レポートはこちら</a></p>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 06:16:11','2019-10-15 06:29:30'),(45,2,'【部品・装飾品】アクリルツマミ','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">アクリサンデー接着剤で簡単に取付可能な透明のアクリルツマミ。</li>\r\n        <li class=\"list__item\">アクリルケース等の開閉扉に使用した際に目立ちません。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami-acrylic/knob600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>アクリルツマミを取り付ける位置を決めます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami-acrylic/knob600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ツマミの手前側を少し浮かせた状態で固定し、注入器の針を刺し込んで接着剤を流し込みます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami-acrylic/knob600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ツマミの接着面に入った空気を押し出すように指で軽く押します。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">強く押さえたり位置をずらしたりすると、接着面が汚くなってしまうので、注意しましょう。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami-acrylic/knob600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>30分程度動かさないように放置して完全に乾いたら完成です。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 06:27:59','2019-07-18 04:36:40'),(46,4,'【部品・装飾品】アクリルツマミ','<h3 class=\"section__caption c-heading--sm\">アクリルツマミ</h3>\r\n<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">接着取付専用</li>\r\n  </ul>\r\n  <table class=\"c-table--sm u-width--70 u-margin--top-8\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\">サイズ</th>\r\n        <td>直径15mmx長さ20mm</td>\r\n      </tr>\r\n      <tr>\r\n        <th>数量</th>\r\n        <td>1個入り</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 06:28:36','2019-06-22 04:37:43'),(47,4,'【部品・装飾品】アクリルツマミ(ねじ止め)','<h3 class=\"section__caption c-heading--sm\">アクリルツマミ ねじ止め</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-whitespace--nowrap\">\r\n    <thead>\r\n      <tr>\r\n        <th></th>\r\n        <th>ツマミ</th>\r\n        <th>トラスネジ</th>\r\n        <th>有効深さ(X)</th>\r\n        <th>数量</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr>\r\n        <th>M3</th>\r\n        <td>直径15mm×長さ20mm</td>\r\n        <td>L10</td>\r\n        <td>有効8mm</td>\r\n        <td>ツマミ×1個 トラスネジ×1本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>M4</th>\r\n        <td>直径15mm×長さ20mm</td>\r\n        <td>L12</td>\r\n        <td>有効10mm</td>\r\n        <td>ツマミ×1個 トラスネジ×1本</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 06:39:49','2019-12-12 05:26:50'),(48,2,'【部品・装飾品】アクリルツマミ(ねじ止め)','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">ネジで固定する透明アクリルツマミのネジセット。</li>\r\n        <li class=\"list__item\">透明素材の為、取り付け部は目立ちません。</li>\r\n        <li class=\"list__item\">ネジ止めなので、取り付けが簡単です。</li>\r\n        <li class=\"list__item\">DIYに最適です。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami/tumami600-1.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ツマミを付けたい箱を用意します。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami/tumami600-2.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>穴を開ける位置を決めます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami/tumami600-3.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>位置を決めたらドリル等で箱に穴を開けます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami/tumami600-4.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>穴が開いたら、裏側からネジを通してツマミを固定します。ツマミのネジ穴が潰れない程度に軽く締めます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/tsumami/tumami600-5.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>これで完成です。</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 06:44:58','2019-06-05 05:01:00'),(49,2,'【部品・装飾品】アクリル補強棒セット','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">接着のコーナー部分に貼り付けて強度を高めたり、工作などに使用できる補強棒（細棒）セット。</li>\r\n        <li class=\"list__item\">カラーはクリアーのみ。三角・四角・丸の断面形状があります。</li>\r\n        <li class=\"list__item\">長さは全て１ｍ(若干長め)です</li>\r\n        <li class=\"list__item\">ニッパーかカッターナイフで筋を付けて曲げるとカットできます。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/acrylicbar/acrylicbar600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>補強したいアクリル品（写真は箱型ケース）、補強棒（三角）、接着剤、ニッパーを準備します。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/acrylicbar/acrylicbar600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>補強したい部分に補強棒を合わせ、必要な長さを測り、ニッパーで軽く切り込みを入れます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/acrylicbar/acrylicbar600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>一度アクリルケースから補強棒を外し、切り込みを入れた部分をニッパーで切ります。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">アクリルケースに当てたままでカットすると、ケースに傷が付く可能性がありますので、ケースから外して作業することをお勧めします。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/acrylicbar/acrylicbar600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>補強したい部分に補強棒を置き、隙間から接着剤を適量流し込みます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">先にケースに接着剤を流してから補強棒を合わせると、上手く希望の位置に接着できません。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/acrylicbar/acrylicbar600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>補強棒は平面が出ていない為に空気が入りやすいので、指やスクレーパー等で気泡を押し出すように軽く補強棒を押さえてください。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">強く抑えすぎると接着剤が溢れてくるので、軽く押さえるようにしてください。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/acrylicbar/acrylicbar600-06.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>接着剤が乾いたら完成です（左写真は３ヵ所に補強棒を接着しています）。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">補強棒が長すぎた場合には、ヤスリ等で仕上げてください。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 07:01:57','2022-10-03 06:36:01'),(50,4,'【部品・装飾品】アクリル補強棒セット','<h3 class=\"section__caption c-heading--sm\">アクリル補強棒セット</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-width--70\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\"></th>\r\n        <th>入数</th>\r\n      </tr>\r\n      <tr>\r\n        <th>三角3mm</th>\r\n        <td>10本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>三角5mm</th>\r\n        <td>5本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>四角2mm</th>\r\n        <td>10本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>四角3mm</th>\r\n        <td>10本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>四角5mm</th>\r\n        <td>5本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>丸2mm</th>\r\n        <td>10本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>丸3mm</th>\r\n        <td>10本</td>\r\n      </tr>\r\n      <tr>\r\n        <th>丸5mm</th>\r\n        <td>5本</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-23 07:04:47','2019-06-22 04:40:45'),(51,5,'【部品・装飾品】アクリル補強棒セット','<section class=\"p-notes c-section\">\r\n  <ul class=\"c-list--disc\">\r\n    <li class=\"list__item\">製法上、厳密な精度は出ておりません。</li>\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</section>','2019-05-23 07:05:53','2019-05-23 07:05:53'),(52,4,'【部品・装飾品】ビーニングサッシ','<h3 class=\"section__caption c-heading--sm\">ビーニングサッシ</h3>\r\n<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">素材：アクリル クリアー</li>\r\n  </ui>\r\n  <table class=\"c-table--sm u-margin--top-8 u-whitespace--nowrap\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\"></th>\r\n        <th>サイズ</th>\r\n      </tr>\r\n      <tr>\r\n        <th>BA-BS-M2（2mm厚用）</th>\r\n        <td>長さ300×高さ20mm、6.5mm厚</td>\r\n      </tr>\r\n      <tr>\r\n        <th>BA-BS-L3（3mm厚用）</th>\r\n        <td>長さ300×高さ15mm、10mm厚</td>\r\n      </tr>\r\n      <tr>\r\n        <th>BA-BS-H3（3mm厚用）</th>\r\n        <td>長さ300×高さ30mm、10mm厚</td>\r\n      </tr>\r\n      <tr>\r\n        <th>BA-BS-H5（5mm厚用）</th>\r\n        <td>長さ300×高さ30mm、8mm厚</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n    <div class=\"js-modal\"><a data-target=\"zumen_0\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>図面を開く</a>\r\n      <div id=\"zumen_0\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/parts/b_sash/b-sash-zumen.gif\" class=\"u-display--block u-margin--auto\">\r\n  </div>\r\n</div>','2019-05-23 07:46:44','2019-12-12 05:29:23'),(53,2,'【部品・装飾品】ビーニングサッシ','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">展示品に合わせて棚や仕切りを自由に移動できる固定部品。</li>\r\n        <li class=\"list__item\">仕切り板（棚板）の厚み2・3・5mm用があります。</li>\r\n        <li class=\"list__item\">アクリサンデー接着剤で簡単に接着できるアクリル製。</li>\r\n        <li class=\"list__item\">バラ売り。※セット販売ではありません</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">使用方法</h2>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-01.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ビーニングサッシを接着するアクリルケースと仕切り板を準備します。今回は、外寸：200×310×33mm（内寸：194×304×30mm）のアクリルケースと、187×30mmの仕切り板を準備しました。なお、<a href=\"/products/detail/229/\" target=\"_blank\">アクリサンデー接着剤</a>を使用する時に、接着剤用の<a href=\"/products/detail/230/\" target=\"_blank\">注射器</a>を使うと接着剤に付属の注入器より綺麗に接着できるのでお勧めです。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-02.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ビーニングサッシ本体にある突起部分（赤丸）が１カ所の場合（BA-BS-H3・BA-BS-H5）、突起が下側になるように設置します。突起部分が2カ所ある場合（BA-BS-M2・BA-BS-L3）は、端面が平らな方（青線）が下側になるように設置します。反対側は端面が丸くなっている為、真っ直ぐ固定できません。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-03.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ビーニングサッシの溝部分に注射器のノズルを当てて接着剤を流し込みます。写真の赤丸部分の溝にノズルを当てると、ノズルが滑らず固定した状態で接着剤を流す事ができます。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">接着剤を流す側を少しだけ浮かせて接着すると、接着剤が流れやすくなります。綺麗に接着するには多少の慣れが必要になりますので、端材で何度か試してから接着する事をお勧めします。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-04.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>3センチ前後の間隔で数回に分けて接着剤を流すと、綺麗に接着できます。接着剤が流れる様子を確認しながら、流す量を調整しましょう。片側の接着が終わったら、反対側にもビーニングサッシを接着します。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">両側のビーニングサッシの位置がずれないように気を付けながら、接着をしましょう。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-05.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>接着剤が完全に乾いたら、ビーニングサッシに仕切り板を差して完成です。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-06.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ビーニングサッシの突起部分が1カ所の製品（BA-BS-H3・BA-BS-H5）の場合は、側面板とビーニングサッシの隙間部分にポップを差し込んで飾る事ができます。</p>\r\n      </div>\r\n    </div>\r\n    <div class=\"section__item l-article--column-2\">\r\n      <div class=\"article__content--w30\"><img src=\"/storage/images/parts/b_sash/b-sash600-07.jpg\" class=\"js-modal--image\"></div>\r\n      <div class=\"article__content--w70\">\r\n        <p>ビーニングサッシはアクリル製なので、<a href=\"/products/detail/224/\" target=\"_blank\">アクリル専用鋸</a>を使用して簡単にカットする事ができます（写真はBA-BS-H3をアクリル専用鋸で半分にカット）。ビーニングサッシの長さや接着位置を変えたり、ケースのサイズや形状を変えたりして、様々な形の陳列棚を作ってみましょう。</p>\r\n        <div class=\"c-flame--xs-gray u-margin--top-8\">\r\n          <p class=\"c-text--md-bold\">■ ポイント</p>\r\n          <p class=\"c-text--sm\">アクリル専用鋸でカットした後に、ヤスリ等で端面を処理すると、見た目が綺麗になります。</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <p class=\"section__item c-text--right\"><a href=\"/blog/product/351/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>使用レポートはこちら</a></p>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"c-heading--sm\">アクリル以外の適用</h3>\r\n      <table class=\"c-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>ポリカーボネート板</th>\r\n            <th>中空ポリカ</th>\r\n            <th>ポリスチレン板</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n            <td>不適</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-23 07:49:40','2019-10-15 05:46:23'),(54,5,'【部品・装飾品】ビーニングサッシ','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__content c-list--disc\">\r\n    <li class=\"list__item\">製法上、製品に欠けがある場合がございます。</li>\r\n    <li class=\"list__item\">厳密な精度は出ておりません。</li>\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</div>','2019-05-23 08:13:30','2019-06-05 05:25:58'),(55,2,'【ペット】バードケージ（鳥かご）ケース 扉付き','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"section__caption c-heading--sm\">保温効果抜群</h3>\r\n      <ul class=\"c-list--disc\">\r\n        <li >扉を閉めればヒーターの熱が逃げ難く、ケージ全体の保温効果が高まります。</li>\r\n      </ul>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"section__caption c-heading--sm\">扉は片手でラクラク開閉</h3>\r\n      <ul class=\"c-list--disc\">\r\n        <li >扉の取手を持ち上げ、ケース上部のガイドレールに沿って水平に押し込むと、扉が収納出来ます。扉を置く場所を考えず、ケースの換気やお手入れが簡単に行えます。</li>\r\n      </ul>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"section__caption c-heading--sm\">防塵対策</h3>\r\n      <ul class=\"c-list--disc\">\r\n        <li >扉を閉める事で全面がケースで覆われる為、ケースからの羽や餌などの飛び散りを防ぎます。</li>\r\n      </ul>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"section__caption c-heading--sm\">防音効果</h3>\r\n      <ul class=\"c-list--disc\">\r\n        <li >完全防音ではありませんが、鳥さんの甲高い鳴き声が籠った様に聞こえ、鳴き声問題を緩和します。</li>\r\n      </ul>\r\n    </div>\r\n    <div class=\"l-article--column-1\">\r\n      <h3 class=\"section__caption c-heading--sm\">規格サイズのケースが合わない方に</h3>\r\n      <ul class=\"c-list--disc\">\r\n        <li >ピッタリの規格サイズが無い時は、「<a href=\"/products/detail/333/\" target=\"_blank\">セミオーダー品</a>」が便利です。ヒーターやサーモスタット用の穴開けも個別に指定できます。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">こだわりの設計</h2>\r\n\r\n      <div class=\"l-article--column-2-center\">\r\n        <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case_d/bird_cage_case_d_3.jpg\" class=\"js-modal--image\"></div>\r\n        <div class=\"article__content--w60\">\r\n          <h3 class=\"c-heading--sm\">ケース側にヒーター設置が可能</h3>\r\n          <p class=\"c-text--md\">ケース外周の穴に、内側からヒーターやサーモスタットを掛けて利用できます。利用者が多いアサヒ・ペットヒーター60Wを設置できる構造です。</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"l-article--column-2-center\">\r\n        <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case_d/bird_cage_case_d_4.jpg\" class=\"js-modal--image\"></div>\r\n        <div class=\"article__content--w60\">\r\n          <h3 class=\"c-heading--sm\">扉を簡単収納</h3>\r\n          <p class=\"c-text--md\">扉はケース上部のガイドレールに沿って収納できるので、鳥かごの出し入れや換気に便利です。</p>\r\n          <p class=\"c-text--note\">収納時に扉の一部が前面に飛び出ます。</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"l-article--column-2-center\">\r\n        <div class=\"article__content--w40\"><img src=\"/storage/images/animal/bird_cage_case_d_semi/bird_cage_case_d_semi_5.jpg\" class=\"js-modal--image\"></div>\r\n        <div class=\"article__content--w60\">\r\n          <h3 class=\"c-heading--sm\">ケースの清掃が簡単に</h3>\r\n          <p class=\"c-text--md\">扉のストッパーの金具を外せば、扉は取り外しできます。ケースの清掃時に便利です。</p>\r\n          <p class=\"c-text--note\">扉無しタイプの「<a href=\"/products/detail/195/\">バードケージケース</a>」もあります。</p>\r\n        </div>\r\n      </div>\r\n  </section>\r\n\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">開閉方法</h2>\r\n      <div class=\"l-article--column-2-center\">\r\n        <div class=\"article__content--w40\">\r\n          <div class=\"c-iframe\">\r\n            <iframe src=\"https://www.youtube.com/embed/cZeMat9zq8Q\" frameborder=\"0\" allow=\"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>\r\n          </div>\r\n        </div>\r\n        <div class=\"article__content--w60\">\r\n          <h3 class=\"c-heading--sm\"></h3>\r\n          <p class=\"c-text--md\">片手で簡単に扉の開閉が行えます。</p>\r\n        </div>\r\n      </div>\r\n  </section>\r\n</div>','2019-05-23 08:14:08','2019-08-02 01:34:29'),(56,4,'【ペット】バードケージ（鳥かご）ケース 扉付き','<div class=\"l-article--column-1\">\r\n  <section class=\"article__content\">\r\n    <h3 class=\"section__caption c-heading--sm\">共通仕様</h3>\r\n    <table class=\"c-table--sm u-width--70\">\r\n      <thead>\r\n        <tr>\r\n          <th>素材</th>\r\n          <td>アクリル</td>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n      <tr>\r\n        <th>板厚</th>\r\n        <td>5mm（背板のみ3mm）</td>\r\n      </tr>\r\n      </tbody>\r\n    </table>\r\n  </section>\r\n\r\n  <section class=\"article__content u-margin--top-32\">\r\n    <h3 class=\"section__caption c-heading--sm\">タイプ別仕様</h3>\r\n    <table class=\"c-table--sm u-whitespace--nowrap\">\r\n      <thead>\r\n        <tr>\r\n          <th></th>\r\n          <th>外寸法</th>\r\n          <th>収納可能最大サイズ</th>\r\n          <th>対象ケージ</th>\r\n          <th>重量</th>\r\n          <th>図面</th>\r\n        </tr>\r\n      </thead>\r\n      <tbody>\r\n        <tr>\r\n          <th>470</th>\r\n          <td>W470×D360×H444mm</td>\r\n          <td>W436×D326×H407mm</td>\r\n          <td>W325×D270×H400以下</td>\r\n          <td>約5.8kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"470\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"470\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case_d/birdcage-case2-zumen470.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n        <tr>\r\n          <th>21</th>\r\n          <td>W420×D458×H435mm</td>\r\n          <td>W386×D424×H398mm</td>\r\n          <td>HOEI21手のり</td>\r\n          <td>約6.3kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"21\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"21\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case_d/21.jpg\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n        <tr>\r\n          <th>500</th>\r\n          <td>W500×D508×H590mm</td>\r\n          <td>W466×D474×H553mm</td>\r\n          <td>HOEI35手のり</td>\r\n          <td>約9.3kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"500\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"500\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case_d/birdcage-case2-zumen500.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n        <tr>\r\n          <th>600</th>\r\n          <td>W610×D553×H635mm</td>\r\n          <td>W576×D519×H596mm</td>\r\n          <td>HOEI465オカメ</td>\r\n          <td>約11.8kg</td>\r\n          <td class=\"js-modal\"><a data-target=\"600\" class=\"js-modal__trigger--open\"><i class=\"c-icon--triangle-r\"></i>寸法図面</a>\r\n            <div id=\"600\" class=\"c-window--md c-form js-modal__content\"><img src=\"/storage/images/animal/bird_cage_case_d/birdcage-case2-zumen600.gif\" class=\"u-display--block u-margin--auto\"></div>\r\n          </td>\r\n        </tr>\r\n      </tbody>\r\n    </table>\r\n  </section>\r\n  <section class=\"article__content\">\r\n    <p class=\"c-text--left u-margin--top-8\">\r\n      <a class=\"c-button--sm-white\" href=\"/storage/images/animal/bird_cage_case_d/bird_cage_case2_manual.pdf\" target=\"_blank\">組立方法</a>\r\n    </p>\r\n    <p class=\"c-text--left\"><a href=\"/storage/images/animal/bird_cage_case/bird-cage-case-handling-manual.pdf\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>取扱説明書</a>\r\n  </section>\r\n</div>\r\n<section class=\"article__content\">\r\n  <h3 class=\"section__caption c-heading--sm\">ご希望サイズが無い場合</h3>\r\n  <div class=\"l-article--column-1\">\r\n    <ul class=\"article__content c-list--disc\">\r\n      <li class=\"list__item\">ご希望のサイズが無い場合は<a href=\"/products/detail/333/\" target=\"_blank\">セミオーダー</a>をご利用下さい。</li>\r\n    </ul>\r\n  </div>\r\n</section>','2019-05-23 08:19:48','2022-12-01 02:55:19'),(57,5,'【ペット】バードケージ（鳥かご）ケース 扉付き','<section class=\"p-notes c-section\">\r\n  <ul class=\"c-list--disc\">\r\n    <li class=\"list__item\">近似サイズのケージでもご利用頂けますが、ケースとケージの間のバランスが悪くなってしまう場合がございます。</li>\r\n    <li class=\"list__item\">扉を閉めた際、ケースと扉の間に数ミリの隙間が出来ます。</li>\r\n    <li class=\"list__item\">アクリルの特性上、扉は多少反りやタワミが出る場合があります。</li>\r\n    <li class=\"list__item\">設置場所が水平でないと、ケースが歪み扉がスムーズに閉まらなくなることがあります。</li>\r\n  </ul>\r\n</section>\r\n<section class=\"p-notes c-section\">\r\n  <h2 class=\"section__title c-heading--lg-border\">ご使用上の注意</h2>\r\n  <ul class=\"c-list--disc\">\r\n    <li class=\"list__item\">本製品は6面体ケースの為、鳥さんの脂粉やフケなどがケース内に籠り易く、鳥さんの病気を引き起こす原因に繋がります。お手入れは小まめに行うよう心掛けて下さい。</li>\r\n    <li class=\"list__item\">保温器具を使用する場合は、暑くなり過ぎることがありますので、温度計の設置やサーモスタットを使用して下さい。</li>\r\n    <li class=\"list__item\">扉の開閉、収納はゆっくり行って下さい。勢いよく行うと、破損の原因となります。</li>\r\n    <li class=\"list__item\">扉はストッパーの所まで引き切ってから閉めて下さい。</li>\r\n    <li class=\"list__item\">ネジの緩みがないか小まめに点検し、緩んでいる場合は増し締めをして下さい。</li>\r\n    <li class=\"list__item\">ヒーターは60W以下の物が推奨になります。アクリルの変形温度60℃以上にならないようにして下さい。 参考レポートは <a href=\"/blog/product/505/\" target=\"_blank\">こちら</a>。</li>\r\n    <li class=\"list__item\">ヒーター取付穴の加工は、製造ロットにより仕上がりが異なる場合がありますが、ご使用時に影響はありません。</li>\r\n  </ul>\r\n</section>','2019-05-23 08:58:04','2024-10-22 06:57:22'),(59,5,'【ペット】バードケージ（鳥かご）ケース','<div class=\"l-article--column-1\">\r\n  <ul class=\"c-list--disc\">\r\n    <li class=\"list__item\">近似サイズのケージでもご利用頂けますが、ケースとケージの間のバランスが悪くなってしまう場合がございます。</li>\r\n    <li class=\"list__item\">バードケージケース500R/L・21R/L・470R/Lは片側専用の為、お好みのタイプをお選び下さい。</li>\r\n    <li class=\"list__item\">ヒーターは60W以下の物が推奨になります。アクリルの変形温度60℃以上にならないようにして下さい。</li>\r\n    <li class=\"list__item\">ヒーター取付穴の加工は、製造ロットにより仕上がりが異なる場合がありますが、ご使用時に影響はありません。</li>\r\n  </ul>\r\n  <p class=\"c-text--left\"><a href=\"/blog/product/505/\" target=\"_blank\"><i class=\"c-icon--triangle-r\"></i>参考レポートはこちら</a></p>\r\n</div>','2019-05-24 06:57:36','2024-10-22 06:56:27'),(60,2,'【部品・装飾品】ポリカねじ','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">ポリカーボネート樹脂を使用しており、透明なので目立ちません。</li>\r\n        <li class=\"list__item\">ボルト、ナット：４セット入り。</li>\r\n      </ul>\r\n    </div>\r\n  </section>\r\n</div>','2019-05-27 00:26:43','2019-06-05 05:33:21'),(61,4,'【部品・装飾品】ポリカねじ','<h3 class=\"section__caption c-heading--sm\">ポリカねじ</h3>\r\n<div class=\"l-article--column-1\">\r\n  <table class=\"c-table--sm u-width--70\">\r\n    <tbody>\r\n      <tr>\r\n        <th class = \"u-width--40\">素材</td>\r\n        <td>ポリカーボネート樹脂</td>\r\n      </tr>\r\n      <tr>\r\n        <th>サイズ</th>\r\n        <td>直径6mm×長さ20mm</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>','2019-05-27 00:28:50','2019-12-04 06:27:05'),(62,5,'【部品・装飾品】ポリカねじ','<div class=\"l-article--column-1\">\r\n  <ul class=\"article__contentc-list--disc\">\r\n    <li class=\"list__item\">金属ねじより強度が落ちるので、荷重の掛かる個所には適しません。</li>\r\n    <li class=\"list__item\">本製品の数量割引はございません。</li>\r\n  </ul>\r\n</div>','2019-05-27 00:30:02','2019-06-05 05:34:47'),(63,2,'【部品・装飾品】光ファイバー','<div class=\"promotion__detail\">\r\n  <section class=\"detail__section\">\r\n    <h2 class=\"c-heading--lg-border\">製品特長</h2>\r\n    <div class=\"l-article--column-1\">\r\n      <ul class=\"article__content c-list--disc\">\r\n        <li class=\"list__item\">アクリルをベースとした光ファイバー。 </li>\r\n        <li class=\"list__item\">光る造花、室内装飾、サイン、プラモデル、その他工作に便利。</li>\r\n        <li class=\"list__item\">光源：ファイバースポットライト</li>\r\n        <li class=\"list__item\">工作：\r\n          <a data-target=\"zumen_0\" class=\"js-modal__trigger--open\">光ファイバーのやさしい工