  <tr>\r\n                                                                  <th>上空間</th>\r\n                                                                  <td>30mm (高さ150mmの20%)</td>\r\n                                                                </tr>\r\n                                                                <tr>\r\n                                                                  <th>ご注文時のケース横幅サイズ</th>\r\n                                                                  <td>100＋30＋30＋(板厚3mm × 2)=166mm</td>\r\n                                                                </tr>\r\n                                                                <tr>\r\n                                                                  <th>ご注文時のケース高さサイズ</th>\r\n                                                                  <td>150＋30＋(板厚3mm)=183mm</td>\r\n                                                                </tr>\r\n                                                              </tbody>\r\n                                                            </table>\r\n                                                          </div>\r\n                                                          <div class=\"article__content\">\r\n                                                            <p class=\"c-text--md-weightBold-center\">奥行の参考</p><img src=\"/assets/images/products/semi_order/37/img_step3_03.jpg\">\r\n                                                            <table class=\"c-table\">\r\n                                                              <thead>\r\n                                                                <tr>\r\n                                                                  <th colspan=\"2\" class=\"c-text--center\">フィギュア奥行6060mmの例</th>\r\n                                                                </tr>\r\n                                                              </thead>\r\n                                                      