                                                               <div class=\"form__select\">\r\n                                                                            <select name=\"square_angle4\" id=\"square_angle4\" onchange=\"input_restriction(1)\">\r\n                                                                              <option value=\"\" selected=\"\">選択</option>\r\n                                                                              <option value=\"R5\">R5</option>\r\n                                                                              <option value=\"R2\">R2</option>\r\n                                                                            </select>\r\n                                                                          </div>\r\n                                                                        </div>\r\n                                                                      </div>\r\n                                                                    </dd>\r\n                                                                  </dl>\r\n                                                                </div>\r\n                                                                <div class=\"section__buttonSet\">\r\n                                                                  <button class=\"buttonSet__add c-button--xs-primary js-addContent__trigger--add\">加工を追加する</button>\r\n                                                                  <button onclick=\"square_clear()\" class=\"buttonSet__clear c-button--xs-gray\">クリア</button>\r\n                                                                </div>\r\n                                                              </div>\r\n                                                            </div>\r\n                                                            <div class=\"l-article--column-1\">\r\n                                                              <div class=\"ar