--
-- Table structure for table `product_settings`
--

DROP TABLE IF EXISTS `product_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `product_settings` (
  `product_setting_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `picture_priority` tinyint(1) DEFAULT NULL COMMENT '0:未設定（商品）\r\n1:カラー別\r\n2:サイズ別\r\n3:オプション別',
  `form_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `add_cart_function` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cart_parameter_quantity` int unsigned DEFAULT NULL,
  `is_color_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `color_display_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_group_id` bigint unsigned DEFAULT NULL,
  `is_size_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `size_group_id` bigint unsigned DEFAULT NULL,
  `specify_size` tinyint(1) DEFAULT NULL COMMENT '1:規格サイズ(数値)\r\n2:規格サイズ(文字列)\r\n3:自由入力',
  `specification_size_numerical_display` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specification_size_numerical_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specification_size_numerical_wh_limit` bigint unsigned DEFAULT NULL,
  `specification_size_string_display` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specification_size_string_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `free_input_width_display` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `free_input_width_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `free_input_height_display` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `free_input_height_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_free_input_depth_valid` int DEFAULT NULL COMMENT '1:有効0:無効',
  `free_input_depth_display` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `free_input_depth_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `free_input_wdh_limit` bigint unsigned DEFAULT NULL,
  `is_plate_thickness_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `plate_thickness_display` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '\r\n',
  `plate_thickness_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_product_option_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `is_destination_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `destination_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `destination_initial` bigint DEFAULT NULL COMMENT '1:個人 2:法人',
  `is_quantity_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `quantity_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price_calculation_function` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_stock_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `stock_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_delivery_charge_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `delivery_private_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_private_price_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_faraway_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_faraway_price_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_large_delivery_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `large_delivery_html_tag_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_fax_order_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `is_auto_calculation_valid` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1:有効 0:無効',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_setting_id`),
  KEY `product_id` (`product_id`),
  KEY `color_group_id` (`color_group_id`),
  KEY `size_group_id` (`size_group_id`),
  CONSTRAINT `product_settings_ibfk_1` FOREIGN KEY (`color_group_id`) REFERENCES `color_groups` (`color_group_id`),
  CONSTRAINT `product_settings_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`),
  CONSTRAINT `product_settings_ibfk_3` FOREIGN KEY (`size_group_id`) REFERENCES `size_groups` (`size_group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=374 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

