--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `product_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `product_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品コード',
  `product_type_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品種別のcode標準商品:standardセミオーダー:custom',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名',
  `product_name_displayed_cart` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_category_id` bigint unsigned NOT NULL COMMENT '商品カテゴリーのID',
  `is_display` tinyint(1) NOT NULL COMMENT '1:表示\r\n0:非表示',
  `maker_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'メーカー名',
  `product_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '商品概要',
  `picture_id` bigint DEFAULT NULL,
  `price` bigint DEFAULT NULL COMMENT '定価',
  `discount_rate_id` bigint unsigned DEFAULT NULL,
  `delivery_schedule_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '発送予定がまとめられたCSVファイルの4行目の値をセットする',
  `delivery_supplementations` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `related_product_option` tinyint(1) DEFAULT NULL COMMENT '0:タグから表示\r\n1:自由選択',
  `customer_feedback_pc_word` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `number_of_customer_feedback_pc_word` bigint unsigned DEFAULT NULL,
  `customer_feedback_sp_word` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `number_of_customer_feedback_sp_word` bigint unsigned DEFAULT NULL,
  `is_sold_out_notice_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `sold_out_notice` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `display_order` int DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '論理削除用\r\n日付が入っている場合は論理削除',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `versions_string` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`product_id`),
  KEY `uq_products_01` (`product_name`,`product_code`,`product_category_id`,`product_type_code`),
  KEY `idx_products_01` (`product_code`),
  KEY `product_category_id` (`product_category_id`),
  KEY `discount_rate_id` (`discount_rate_id`),
  KEY `idx_product_type` (`product_type_code`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`discount_rate_id`) REFERENCES `discount_rates` (`discount_rate_id`),
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`product_category_id`) REFERENCES `product_categories` (`product_category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=463 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

