--
-- Table structure for table `repair_parts`
--

DROP TABLE IF EXISTS `repair_parts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `repair_parts` (
  `repair_parts_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品コード',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名',
  `set_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_name_displayed_cart` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '商品概要',
  `thumbnail_picture_id` bigint unsigned DEFAULT NULL,
  `price` bigint DEFAULT NULL COMMENT '定価',
  `delivery_schedule_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '発送予定がまとめられたCSVファイルの4行目の値をセットする',
  `display_order` int unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '論理削除用\n日付が入っている場合は論理削除',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`repair_parts_id`),
  KEY `idx_repair_parts_01` (`product_code`,`product_name`),
  KEY `thumbnail_picture_id` (`thumbnail_picture_id`),
  CONSTRAINT `repair_parts_ibfk_1` FOREIGN KEY (`thumbnail_picture_id`) REFERENCES `pictures` (`picture_id`)
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

