--
-- Table structure for table `reviews`
--

DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reviews` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `keyword1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'キーワード1',
  `keyword2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'キーワード2',
  `keyword3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'キーワード3',
  `keyword4` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'キーワード4',
  `keyword5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'キーワード5',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ニックネーム',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'タイトル',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '本文',
  `star` tinyint NOT NULL DEFAULT '0' COMMENT '星１〜５',
  `file` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ファイルの格納パス',
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IPアドレス',
  `host` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HOST名',
  `user_agent` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ユーザーエージェント',
  `inputkey` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'ステータス 公開:true 非公開:false',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '社内メモ',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `reviews_keyword1_index` (`keyword1`),
  KEY `reviews_keyword2_index` (`keyword2`),
  KEY `reviews_keyword3_index` (`keyword3`),
  KEY `reviews_keyword4_index` (`keyword4`),
  KEY `reviews_keyword5_index` (`keyword5`),
  KEY `reviews_inputkey_index` (`inputkey`)
) ENGINE=InnoDB AUTO_INCREMENT=11747 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `reviews`
--

LOCK TABLES `reviews` WRITE;
/*!40000 ALTER TABLE `reviews` DISABLE KEYS */;
INSERT INTO `reviews` VALUES (5154,'箱型アクリルケース',NULL,NULL,NULL,NULL,'hiro',NULL,'箱型ケ－スセミオ－ダ－で届いた製品は予想をはるかに超越したすばらしいものでした。高度な技術力で高級感にあふれ持つ喜びを感じます。ぜひ知人にも知らせようと思います。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'1',1,NULL,NULL,'2012-08-03 15:00:00','2012-08-03 15:00:00'),(5155,'箱型アクリルケース',NULL,NULL,NULL,NULL,'ファントム',NULL,'出来栄え、納期とも十分満足できるものでした。安い単価では難しいかもしれませんが、いろいろと細かい点で相談できるとさらにいいと思います。',5,NULL,NULL,'*.bbtec.net',NULL,'2',1,NULL,NULL,'2012-08-04 15:00:00','2012-08-04 15:00:00'),(5156,'アクリルドーム（半球）　射出成形品',NULL,NULL,NULL,NULL,'M.S.',NULL,'探していたものがこちらにありました。助かります。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'3',1,NULL,NULL,'2012-08-04 15:00:00','2012-08-04 15:00:00'),(5157,'アクリル厚板',NULL,NULL,NULL,NULL,'nakasanda',NULL,'商品の仕上がり、製作期間、梱包等マズマズで特に問題はありません。',5,NULL,NULL,'*.mesh.ad.jp',NULL,'4',1,NULL,NULL,'2012-08-05 15:00:00','2012-08-05 15:00:00'),(5158,'フォトフレーム　スタンダード',NULL,NULL,NULL,NULL,'クリヤ',NULL,'スマートで透明なので、写真が引き立ちます。UVカットで写真が変色し難いとのことで安心しました。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'5',1,NULL,NULL,'2012-08-05 15:00:00','2012-08-05 15:00:00'),(5159,'アクリル押出板',NULL,NULL,NULL,NULL,'あひる',NULL,'指定寸法通りで、ぴったり収まりました。ありがとうございました。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'6',1,NULL,NULL,'2012-08-02 15:00:00','2012-08-02 15:00:00'),(5160,'アクリル押出板',NULL,NULL,NULL,NULL,'tenichi',NULL,'アクリル板のカットをお願いしました。ところが、カット精度がかなり良くてびっくりした次第です。また、納期の早さは非常に満足しています。今後ともよろしくお願い申し上げます。',5,NULL,NULL,'*.amixcom.jp',NULL,'7',1,NULL,NULL,'2012-08-05 15:00:00','2012-08-05 15:00:00'),(5161,'アクリル端材（薄板・厚板）',NULL,NULL,NULL,NULL,'広島市　岩田　正',NULL,'端材とは言え全てカットも綺麗で量も十分あり、価格的には満足ですが、透明が主体でしたので、希望として透明・白・黒等を入れていただければ、再注文したいです。',4,NULL,NULL,'*.bbtec.net',NULL,'8',1,NULL,NULL,'2012-08-08 15:00:00','2012-08-08 15:00:00'),(5162,'アクリルミラー板',NULL,NULL,NULL,NULL,'まさひろｗｗｗ',NULL,'案外鏡になることの方が多くて透明感がいまいち分からなかったが、きれいだった。',3,NULL,NULL,'*.ocn.ne.jp',NULL,'9',1,NULL,NULL,'2012-08-09 15:00:00','2012-08-09 15:00:00'),(5163,'カタログケース屋外用　ステン蝶番タイプ',NULL,NULL,NULL,NULL,'おかぴょん',NULL,'納品が早くたすかりました',3,NULL,NULL,'*.sekisui.jp',NULL,'10',1,NULL,NULL,'2012-08-10 15:00:00','2012-08-10 15:00:00'),(5164,'アクリサンデー　接着剤',NULL,NULL,NULL,NULL,'ナッシュ',NULL,'オーダーフォームで三角形のオーダーのやりかたが解りませんでした。届いた商品は断面も綺麗でとても良かったです。切断料金が少し割高だったと思います。',4,NULL,NULL,'*.kakt.j-cnet.jp',NULL,'11',1,NULL,NULL,'2012-08-10 15:00:00','2012-08-10 15:00:00'),(5165,'箱型アクリルケース',NULL,NULL,NULL,NULL,'jiji',NULL,'セミオ－ダ－で期待以上のすばらしいものでした。高度な技術力を感じ大切にしたいです。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'12',1,NULL,NULL,'2012-08-11 15:00:00','2012-08-11 15:00:00'),(5166,'ポスターフレーム　プロスタイル',NULL,NULL,NULL,NULL,'アム',NULL,'個人でポスターを飾るために、プロスタイルを購入しました。取り付けも簡単で、ポスターの入れ替えも楽に出来るのが良かったです。',5,NULL,NULL,'*.home.ne.jp',NULL,'13',1,NULL,NULL,'2012-08-11 15:00:00','2012-08-11 15:00:00'),(5167,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'ホビー好き',NULL,'とってもわかりやすいHPで注文も楽でした。またアクリル板も好みのサイズに切っていただき、端面処理も美しく完璧でした。迅速に対応していただきました。商品の梱包も丁寧・完璧でした。また機会があれば是非お世話になりたいです！　　ありがとうございました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'14',1,NULL,NULL,'2012-08-11 15:00:00','2012-08-11 15:00:00'),(5168,'ポリカーボネート板',NULL,NULL,NULL,NULL,'ポチ',NULL,'寸法通りに切っていただいて、綺麗に納まりました',5,NULL,NULL,'*.ocn.ne.jp',NULL,'15',1,NULL,NULL,'2012-08-11 15:00:00','2012-08-11 15:00:00'),(5169,'アクリル端材（薄板・厚板）',NULL,NULL,NULL,NULL,'ちょび',NULL,'アクリル板の端材以外の端材（例えばアクリルパイプ・丸棒・角棒等）も販売していただければうれしいです。',4,NULL,NULL,'*.ocn.ad.jp',NULL,'16',1,NULL,NULL,'2012-08-11 15:00:00','2012-08-11 15:00:00'),(5170,'アクリルコレクションケース',NULL,NULL,NULL,NULL,'BJ',NULL,'大変満足',5,NULL,NULL,'*.omn.ne.jp',NULL,'17',1,NULL,NULL,'2012-08-11 15:00:00','2012-08-11 15:00:00'),(5171,'ポリカーボネート板',NULL,NULL,NULL,NULL,'神奈川県Y・T',NULL,'素材の種類が豊富にあると思うのですが、もう少し素材・色の種類もあると良いなと思いました。　加工も素人の注文対応は大変だとは思うのですがこんな加工がある。とわかるともっと注文の幅が広がるように思いました。届いた商品の加工はとても良かったと思います。',4,NULL,NULL,'*.dion.ne.jp',NULL,'18',1,NULL,NULL,'2012-08-12 15:00:00','2012-08-12 15:00:00'),(5172,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'のりちゃん',NULL,'全体的に満足したが、思っていた以上に重かった。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'19',1,NULL,NULL,'2012-08-12 15:00:00','2012-08-12 15:00:00'),(5173,'アクリル押出板',NULL,NULL,NULL,NULL,'ブチョー',NULL,'注文が簡単に行えました。品物はすぐに届き、切断もとてもキレイでした。おきなサイズのアクリル板は自分で切るとキズや削りカスで苦労しますが、切断サービスがあるのは大いに助かります。',5,NULL,NULL,'*.jway.ne.jp',NULL,'20',1,NULL,NULL,'2012-08-05 15:00:00','2012-08-05 15:00:00'),(5174,'色紙額',NULL,NULL,NULL,NULL,'ユーイチ',NULL,'大事にしていた色紙を綺麗に飾りたかったのと長期間、色あせを防ぎたかったのでこちらのUV防止加工の色紙用アクリルフレームを購入しました。実際にフレームに収め、飾ると見栄えも良く、いつでも目にすることができるので大変満足してしています。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'21',1,NULL,NULL,'2012-08-13 15:00:00','2012-08-13 15:00:00'),(5175,'アクリサンデー　接着剤',NULL,NULL,NULL,NULL,'石見の国',NULL,'アクリルパイプ購入いたしました。フランジ付があれば最高にいいのですが・・・',4,NULL,NULL,'*.yournet.ne.jp',NULL,'22',1,NULL,NULL,'2012-08-13 15:00:00','2012-08-13 15:00:00'),(5176,'アクリル押出板',NULL,NULL,NULL,NULL,'hm',NULL,'大きめに注文して切りわけを自分で行ったのですが、こつをつかむまで結構苦労しました。切り口周辺にうっかりした傷も出来てしまうし次は慣れると良いと思いました。筋目の入れ方などコツが動画などで解説されているとより身近な工作素材になるのではないでしょうか。',5,NULL,NULL,'*.asahi-net.or.jp',NULL,'23',1,NULL,NULL,'2012-08-13 15:00:00','2012-08-13 15:00:00'),(5177,'アクリル押出板',NULL,NULL,NULL,NULL,'chaahyuu',NULL,'迅速な対応で非常に助かりました。',5,NULL,NULL,'*.kanden.ne.jp',NULL,'24',1,NULL,NULL,'2012-08-15 15:00:00','2012-08-15 15:00:00'),(5178,'箱型アクリルケース',NULL,NULL,NULL,NULL,'神奈川県ｄｉａｎａ',NULL,'今回で、3個目の注文です。オーダーなのに、お値段が手頃で、見積もりも簡単で、とても気に入っています。ＬＥＧＯやフィギャを飾ってますが、ほこりもつかなくなり、掃除も楽で、作ってよかったです。',5,NULL,NULL,'*.dion.ne.jp',NULL,'25',1,NULL,NULL,'2012-08-16 15:00:00','2012-08-16 15:00:00'),(5179,'箱型アクリルケース',NULL,NULL,NULL,NULL,'かずお',NULL,'素晴らしい制作技術に満足です。また、梱包も丁寧で安心して再注文できます。輸送事故を心配された注意書きも完璧です。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'26',1,NULL,NULL,'2012-08-17 15:00:00','2012-08-17 15:00:00'),(5180,'アクリサンデー　静電気防止ポリケア',NULL,NULL,NULL,NULL,'兵庫KE',NULL,'特に問題なく使用しています。',5,NULL,NULL,'61.114.249.129',NULL,'27',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5181,'アクリル押出板',NULL,NULL,NULL,NULL,'ダンボ',NULL,'北海道の僻地住まいのため、早い対応に大満足です。初めて利用しましたが、またお願いします。',5,NULL,NULL,'*.dion.ne.jp',NULL,'28',1,NULL,NULL,'2012-08-16 15:00:00','2012-08-16 15:00:00'),(5182,'アクリル押出板',NULL,NULL,NULL,NULL,'しゃむ',NULL,'対応が早く、大変満足しています。',4,NULL,NULL,'*.infoweb.ne.jp',NULL,'29',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5183,'アクリサンデー　接着剤',NULL,NULL,NULL,NULL,'pixyblack',NULL,'アクリサンデー接着剤が予想以上に水っぽく、接着時に他に流れ出てしまった。初めてもあり、扱いが難しかった。アクリル板5mmはそれなりに厚く頑丈だが、カッターで切るのに、それなりのパワーと時間が必要（＾＾A',4,NULL,NULL,'*.ocn.ne.jp',NULL,'30',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5184,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'Chinpann',NULL,'不明点に丁寧に対応していただき、安心しました。',4,NULL,NULL,'*.infoweb.ne.jp',NULL,'31',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5185,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'ぬまちゃん',NULL,'注文の仕方について最初はとまどいましたが、機械関連にたずさわっていたので、なれれば確認が非常に楽でした。特に注文した加工が図面で出てくるのが表情に良いです。また、早い、安いで今回非常に満足しました。',5,NULL,NULL,'*.dion.ne.jp',NULL,'32',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5186,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'H.I.',NULL,'早く届きましたし、製品もしっかりしていて気に入りました。梱包も必要最小限のシンプルかつ丁寧。また機会があったらお願いします。',5,NULL,NULL,'*.t-com.ne.jp',NULL,'33',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5187,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'匿名',NULL,'今回初めて購入しました。比較のしようがないのですが、ポスターとポストカードをお部屋に飾るのに使用してみて、高級な感じに見えて良かったです。…が、ちょっと高いです(^^;)ＵＶカットがどの程度効果があるのか、経過を楽しみにしてます。',4,NULL,NULL,'*.plala.or.jp',NULL,'34',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5188,'アクリルキャスト板',NULL,NULL,NULL,NULL,'山口県 TERA',NULL,'二回目の利用でしたが今回はメーカー直送の商品の数量確認に不備があったみたいでした。それ以外は問題ありません。',4,NULL,NULL,'*.bbtec.net',NULL,'35',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5189,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'SP',NULL,'アクリル専門の会社の製作なので　安くてもきれいに仕上げていただきました。',5,NULL,NULL,'*.prin.ne.jp',NULL,'36',1,NULL,NULL,'2012-08-20 15:00:00','2012-08-20 15:00:00'),(5190,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'KX1K',NULL,'取り付けも簡単できれいに設置することができまた。取り付け金具も綺麗に隠れて、フロート部分も壁にぴったりでした。良い商品だと思います。',5,NULL,NULL,'*.megaegg.ne.jp',NULL,'37',1,NULL,NULL,'2012-08-20 15:00:00','2012-08-20 15:00:00'),(5191,'アクリル押出板',NULL,NULL,NULL,NULL,'鹿児島県Ｈ．Ｉ',NULL,'障子のガラスを、子供の怪我防止のためにアクリルに入替えました。すりガラス風のアクリル板で、希望のサイズに切断して納入してもらえるので助かりました。２mm厚を16枚購入したのですが、梱包が少し雑なのが気になりました。宅配業者が持ってきた際に少々反っていましたので、添え木などが入っていれば尚良かったです',5,NULL,NULL,'*.plala.or.jp',NULL,'38',1,NULL,NULL,'2012-08-19 15:00:00','2012-08-19 15:00:00'),(5192,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'まもる',NULL,'家で使っているブルーレイプレーヤーの上に、アップル社のWi-Fiルータを載せるための台を注文しました。イラスト図の通りに作成して頂き、とてもスタイリッシュで綺麗な台が出来て感激しています。自分でアクリルの接着等の加工をしたことがないので、やはり専門家に依頼するのが最も適切と分かりました。ありがとうございました。',5,NULL,NULL,'*.tcat.ne.jp',NULL,'39',1,NULL,NULL,'2012-08-20 15:00:00','2012-08-20 15:00:00'),(5193,'アクリル押出板',NULL,NULL,NULL,NULL,'mituko',NULL,'迅速丁寧、確実なお取引をしていただきありがとうございました。これからもよろしくお願いいたします。',5,NULL,NULL,'*.eonet.ne.jp',NULL,'40',1,NULL,NULL,'2012-08-20 15:00:00','2012-08-20 15:00:00'),(5194,'ガルウイングケース',NULL,NULL,NULL,NULL,'J',NULL,'フィギュアを飾るための購入は初めてですが、商品にはとても満足しています。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'41',1,NULL,NULL,'2012-08-22 15:00:00','2012-08-22 15:00:00'),(5195,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'K',NULL,'見た感じより、重い',3,NULL,NULL,'*.nttpc.ne.jp',NULL,'42',1,NULL,NULL,'2012-08-23 15:00:00','2012-08-23 15:00:00'),(5196,'アクリル押出板',NULL,NULL,NULL,NULL,'大阪府　ディー',NULL,'急な注文にも迅速に対応してくださいました。おかげで納期にもばっちり間に合いました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'43',1,NULL,NULL,'2012-08-20 15:00:00','2012-08-20 15:00:00'),(5197,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'SIHUZAHU',NULL,'今回A3サイズのポスターフレームを購入しましたが、サイズが大きくなるほど、ほこりやゴミの不着を防ぎつつ挟み込むのが難しくなりますね。良い方法があればHPへのアップよろしくお願いいたします。',4,NULL,NULL,'*.ocn.ne.jp',NULL,'44',1,NULL,NULL,'2012-08-26 15:00:00','2012-08-26 15:00:00'),(5198,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'toku',NULL,'きれいな仕上がりでした。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'45',1,NULL,NULL,'2012-08-26 15:00:00','2012-08-26 15:00:00'),(5199,'アクリル端材（薄板・厚板）',NULL,NULL,NULL,NULL,'コプエル',NULL,'アクリルでプラモデル模型の台座を制作したい為、練習用に端材とアクリル用接着剤などを購入。端材の量と品質に驚きました。とても綺麗で意欲がわきました。「アクリルの加工方法－切る/削る-チップソー」を参考にカットにも挑戦しようと思います。',5,NULL,NULL,'*.tv-tokyo.co.jp',NULL,'46',1,NULL,NULL,'2012-08-27 15:00:00','2012-08-27 15:00:00'),(5200,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'魚返如水',NULL,'アクリル板のねじ切りがインチ表記の特殊仕様でしたが、技術問合せ窓口のご担当の方が親切に対応下さり、試作品無事に完成しました。フルカスタム扱いになりましたが、価格もリーズナブルで満足しています。土曜日にも発送頂け迅速なご対応に感謝しています。',5,NULL,NULL,'210.123.94.26',NULL,'47',1,NULL,NULL,'2012-08-27 15:00:00','2012-08-27 15:00:00'),(5201,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'NT',NULL,'お願いした通りに穴を開けて下さったアクリル板と指定した長さに切ったアクリル管をお届けくださいまして、ありがとうございました。初めてお願いしましたが、満足できるものをお届けくださいました。これからも利用したいと感じています。',5,NULL,NULL,'*.biz.rr.com',NULL,'48',1,NULL,NULL,'2012-08-27 15:00:00','2012-08-27 15:00:00'),(5202,'ユニフォーム額',NULL,NULL,NULL,NULL,'サザエさん',NULL,'満足です。思った以上にきれいに飾れました。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'49',1,NULL,NULL,'2012-08-28 15:00:00','2012-08-28 15:00:00'),(5203,'フォトフレームクロック',NULL,NULL,NULL,NULL,'フラワー',NULL,'絵を時々交換して、気分転換できるのがとっても良いですね。季節によって絵を変えてみようと思います。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'50',1,NULL,NULL,'2012-08-28 15:00:00','2012-08-28 15:00:00'),(5204,'箱型アクリルケース',NULL,NULL,NULL,NULL,'よ',NULL,'オーダーメイドに細かく対応してくださり感謝しています',5,NULL,NULL,'*.mesh.ad.jp',NULL,'51',1,NULL,NULL,'2012-08-29 15:00:00','2012-08-29 15:00:00'),(5205,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'いつぼん',NULL,'加工も綺麗で見た目はとても満足しました。ただガラスに近い感覚で考えていた予想を裏切り、物を乗せるとすぐにたわんでしまいました。アクリルは好きなのですが、今後は用途によって諦める覚悟も必要と実感しました。',2,NULL,NULL,'*.infoweb.ne.jp',NULL,'52',1,NULL,NULL,'2012-08-30 15:00:00','2012-08-30 15:00:00'),(5206,'アクリル型模様板',NULL,NULL,NULL,NULL,'VFR1200F',NULL,'注文したサイズ通りの加工、発送も短期間で大助かりでした。',4,NULL,NULL,'*.infoweb.ne.jp',NULL,'53',1,NULL,NULL,'2012-08-30 15:00:00','2012-08-30 15:00:00'),(5207,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'tomo',NULL,'お盆中の注文でしたが、お盆明け直ぐに対応頂き、発送までの時間には満足しております。また、今回アクリル板のカットやくり抜きなどもお願いしましたが、オーダー画面も分かりやすく希望通りのできあがりでした。価格面も自分でアクリル板を購入して加工することを考えると妥当な金額だと思います。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'54',1,NULL,NULL,'2012-08-31 15:00:00','2012-08-31 15:00:00'),(5208,'アクリル押出板',NULL,NULL,NULL,NULL,'エスケイ',NULL,'商品届きました。有り難うございます。',5,NULL,NULL,'*.eonet.ne.jp',NULL,'55',1,NULL,NULL,'2012-08-25 15:00:00','2012-08-25 15:00:00'),(5209,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'ぽり',NULL,'テーブル天板用のアクリル板を購入しました。梱包とてもしっかりしていました。特注加工の部分もしっかりした仕上がりでした。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'56',1,NULL,NULL,'2012-08-31 15:00:00','2012-08-31 15:00:00'),(5210,'フォトフレーム　スタンダード',NULL,NULL,NULL,NULL,'ナチュ',NULL,'すっきりしていて気に入っています。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'57',1,NULL,NULL,'2012-08-31 15:00:00','2012-08-31 15:00:00'),(5211,'テーブルマット　セミオーダー',NULL,NULL,NULL,NULL,'まさ',NULL,'テーブルサイズが大きいので注文不可能な店も多かったのですが、アクリ屋さんは大きなサイズにも対応可能で、梱包もしっかりしていました。楕円のカットや加工も綺麗で、ジャストサイズでした。',5,NULL,NULL,'*.plala.or.jp',NULL,'58',1,NULL,NULL,'2012-08-31 15:00:00','2012-08-31 15:00:00'),(5212,'アクリル押出板',NULL,NULL,NULL,NULL,'i',NULL,'梱包が丁寧でした',5,NULL,NULL,'*.plala.or.jp',NULL,'59',1,NULL,NULL,'2012-08-31 15:00:00','2012-08-31 15:00:00'),(5213,'アクリル押出板',NULL,NULL,NULL,NULL,'たらおっち',NULL,'二重サッシのDIYに挑戦するために、貴社のアクリル板を購入しました。サイズと枚数にちょっと手違いがありまして、ご担当の方の親切な対応をして頂いたお陰でとても素敵なものができました。アクリル板って高いのでこちらの値段なら予算的に申し分なかったです。重量があるのでこれからのメンテナンスに心配がありますが、なんとかやっていけたらなあと思います。',4,NULL,NULL,'*.cyberhome.ne.jp',NULL,'60',1,NULL,NULL,'2012-09-01 15:00:00','2012-09-01 15:00:00'),(5214,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'hiro',NULL,'思っていたほど重くなく、それでいてまったくチープな感じが有りません。確りとした重量感があり、商品もとても際立つことができました。大変満足できました。',4,NULL,NULL,'*.bbtec.net',NULL,'61',1,NULL,NULL,'2012-09-01 15:00:00','2012-09-01 15:00:00'),(5215,'箱型アクリルケース',NULL,NULL,NULL,NULL,'熊本ＮＴ',NULL,'オーダーが容易で確実にできる。製品の仕上がりが奇麗。荷送りの梱包が丁寧。全てに満足できました。有難うございました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'62',1,NULL,NULL,'2012-09-02 15:00:00','2012-09-02 15:00:00'),(5216,'箱型アクリルケース',NULL,NULL,NULL,NULL,'ジー',NULL,'リピーターですが、今回も、とっても美しく仕上がっていて大満足です。また、注文させて戴きます。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'63',1,NULL,NULL,'2012-09-02 15:00:00','2012-09-02 15:00:00'),(5217,'アクリルパイプ/丸棒加工　セミオーダー',NULL,NULL,NULL,NULL,'つし',NULL,'欲しい材料の長さにカットしていただき、重宝しています。ありがとうございます。',4,NULL,NULL,'*.tsukuba.ac.jp',NULL,'64',1,NULL,NULL,'2012-09-02 15:00:00','2012-09-02 15:00:00'),(5218,'アクリル押出板',NULL,NULL,NULL,NULL,'北海道でラテンだぜー',NULL,'透明のアクリル板を屋外演奏時の楽譜飛散防止用に購入しました。重さがちょうど良く重宝しています。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'65',1,NULL,NULL,'2012-09-01 15:00:00','2012-09-01 15:00:00'),(5219,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'け～坊ちゃん',NULL,'採寸が良かったのか、加工が良かったのか、いずれにしてもピッタシで早速テーブルクロスの上にセットしました。',5,NULL,NULL,'*.bbtec.net',NULL,'66',1,NULL,NULL,'2012-09-03 15:00:00','2012-09-03 15:00:00'),(5220,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'ちびまる男',NULL,'送った図面を忠実に再現して頂きました。技術力の高さに関心しました。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'67',1,NULL,NULL,'2012-09-03 15:00:00','2012-09-03 15:00:00'),(5221,'けんどん式アクリルケース',NULL,NULL,NULL,NULL,'山梨のオシン',NULL,'繊細で綺麗に仕上げていただと感じています。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'68',1,NULL,NULL,'2012-09-03 15:00:00','2012-09-03 15:00:00'),(5222,'箱型アクリルケース',NULL,NULL,NULL,NULL,'なつしま',NULL,'しっかりとした作りで、台座ともぴったりあっており満足しています。また機会があればお願いするつもりです。',5,NULL,NULL,'*.nttpc.ne.jp',NULL,'69',1,NULL,NULL,'2012-09-03 15:00:00','2012-09-03 15:00:00'),(5223,'アクリル押出板',NULL,NULL,NULL,NULL,'ムギ',NULL,'アクリルを注文させていただきました。細かいミリ指定でのカットでしたが、迅速に対応していただきました。　',4,NULL,NULL,'*.bbtec.net',NULL,'70',1,NULL,NULL,'2012-09-02 15:00:00','2012-09-02 15:00:00'),(5224,'アクリル端材（薄板・厚板）',NULL,NULL,NULL,NULL,'まこと',NULL,'　個人ユーザーには、十分過ぎるぐらいの商品でした。',5,NULL,NULL,'*.pcsitebrowser.ne.jp',NULL,'71',1,NULL,NULL,'2012-09-05 15:00:00','2012-09-05 15:00:00'),(5225,'アクリルミラー板',NULL,NULL,NULL,NULL,'rkpp',NULL,'注文から手元に届くまでがとても速かったです。また利用させていただきます。',5,NULL,NULL,'*.mesh.ad.jp',NULL,'72',1,NULL,NULL,'2012-09-05 15:00:00','2012-09-05 15:00:00'),(5226,'アクリル押出板',NULL,NULL,NULL,NULL,'マスター３',NULL,'非常によい製品です。学校のため、多色を多くすると高くなるので、色をまとめましたが、多くの色をお値打ちに購入できるとよい。',4,NULL,NULL,'*.nagoya-c.ed.jp',NULL,'73',1,NULL,NULL,'2012-09-05 15:00:00','2012-09-05 15:00:00'),(5227,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'ara-K',NULL,'ポスターフレーム、セミオーダーで購入。当たり前ですがサイズはぴったりで商品には満足です。飾る場所によっては思ったより反射があるので、次回はけちらず低反射のものにします。',4,NULL,NULL,'*.vectant.ne.jp',NULL,'74',1,NULL,NULL,'2012-09-06 15:00:00','2012-09-06 15:00:00'),(5228,'アクリル押出板',NULL,NULL,NULL,NULL,'やまちゃん',NULL,'サイズぴったりで梱包もしっかりしてました。',5,NULL,NULL,'*.dion.ne.jp',NULL,'75',1,NULL,NULL,'2012-09-06 15:00:00','2012-09-06 15:00:00'),(5229,'オリジナル透明蝶番',NULL,NULL,NULL,NULL,'いけだ',NULL,'注文してからすぐに届きました。ありがとうございます。',4,NULL,NULL,'*.zaq.ne.jp',NULL,'76',1,NULL,NULL,'2012-09-07 15:00:00','2012-09-07 15:00:00'),(5230,'箱型アクリルケース',NULL,NULL,NULL,NULL,'うなぎだ',NULL,'フィギュア用に背面・土台ミラー、UVカット仕様のケースを購入しました。仕上がりが美しく、非常に満足しています。ありがとうございました。',5,NULL,NULL,'*.mesh.ad.jp',NULL,'77',1,NULL,NULL,'2012-09-08 15:00:00','2012-09-08 15:00:00'),(5231,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'わっきー',NULL,'加工もお願いしたのですが、早くてていねいな仕事にびっくりです。他の御店も利用していましたが、今後はこちらで決まりですね。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'78',1,NULL,NULL,'2012-09-08 15:00:00','2012-09-08 15:00:00'),(5232,'アクリル押出板',NULL,NULL,NULL,NULL,'hiro',NULL,'すぐに状態を確認するようメールに書いてあったこともあり、商品到着後に中身を確認しましたが大変綺麗な状態でした。元々他より値段が比較的安い上に包装も丁寧だったので満足しています。また機会があれば是非利用します。今回はありがとうございました。',5,NULL,NULL,'*.c3-net.ne.jp',NULL,'79',1,NULL,NULL,'2012-09-07 15:00:00','2012-09-07 15:00:00'),(5233,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'PAN',NULL,'震災で被災後、再建した社屋ｴﾝﾄﾗﾝｽに社訓掲示用として購入しましたが、雰囲気も良くマッチしており、申し分ありませんでした。これからも、良いものを提案頂ければと思います。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'80',1,NULL,NULL,'2012-09-08 15:00:00','2012-09-08 15:00:00'),(5234,'箱型アクリルケース',NULL,NULL,NULL,NULL,'Sandomierz',NULL,'いつも購入させていただいていますが、とてもしっかりしていて使いやすく、重宝しています。納期が1週間ほどかかるのがもっと短縮していただけると助かるのですがね...。',5,NULL,NULL,'*.dion.ne.jp',NULL,'81',1,NULL,NULL,'2012-09-09 15:00:00','2012-09-09 15:00:00'),(5235,'アクリル押出板',NULL,NULL,NULL,NULL,'sawaotu',NULL,'概ね想定どおりで満足です',4,NULL,NULL,'*.mesh.ad.jp',NULL,'82',1,NULL,NULL,'2012-09-08 15:00:00','2012-09-08 15:00:00'),(5236,'アクリル押出板',NULL,NULL,NULL,NULL,'けい',NULL,'綺麗な仕上げで満足です。',4,NULL,NULL,'*.ocn.ne.jp',NULL,'83',1,NULL,NULL,'2012-09-09 15:00:00','2012-09-09 15:00:00'),(5237,'油彩キャンバス立体額',NULL,NULL,NULL,NULL,'まっこりー',NULL,'電話での相談にも親切に乗って頂き非常に助かりました。また注文します。',5,NULL,NULL,'*.spmode.ne.jp',NULL,'84',1,NULL,NULL,'2012-09-09 15:00:00','2012-09-09 15:00:00'),(5238,'アクリル押出板',NULL,NULL,NULL,NULL,'KF',NULL,'実物を見ない状態での注文で不安もありましたが、思った通りの品が来て、大変満足しています。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'85',1,NULL,NULL,'2012-09-09 15:00:00','2012-09-09 15:00:00'),(5239,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'しお',NULL,'価格が明瞭、事前に分かるので気楽に発注できます。仕上がりはもちろん綺麗で（自分で加工するなると、機材も必要ですし、歩留まりも悪い）気持ちよく使えます。種類も豊富で助かっています。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'86',1,NULL,NULL,'2012-09-11 15:00:00','2012-09-11 15:00:00'),(5240,'箱型アクリルケース',NULL,NULL,NULL,NULL,'cn9a.gsr',NULL,'1/24 スケールの車のプラモデルを飾る為に、2010年に注文した箱型セミオーダーケースを新調。 前回と同じくUVカット仕様で注文したのですが並べてみたらケースの透明度が高くなっていて驚きました。 電話での問い合わせも丁寧に対応してくださり大満足です。',5,NULL,NULL,'*.plala.or.jp',NULL,'87',1,NULL,NULL,'2012-09-11 15:00:00','2012-09-11 15:00:00'),(5241,'アクリルドーム（半球）　射出成形品',NULL,NULL,NULL,NULL,'ペンギン',NULL,'大皿の中華ピヌパヌをディスプレイするのに使用していますが、大変気に入っております。',5,NULL,NULL,'*.pref.iwate.jp',NULL,'88',1,NULL,NULL,'2012-09-12 15:00:00','2012-09-12 15:00:00'),(5242,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'Ｑ１２',NULL,'繋ぎ目があまりきれいではありません。黒だから目立つのかも知れませんが、少し欠けていたり接着剤がはみ出したりしています。',2,NULL,NULL,'*.ocn.ne.jp',NULL,'89',1,NULL,NULL,'2012-09-12 15:00:00','2012-09-12 15:00:00'),(5243,'けんどん式アクリルケース',NULL,NULL,NULL,NULL,'snow',NULL,'非常に素晴らしい出来で驚きました。現在もフィギュアを飾らせて頂いておりますが何度見ても嬉しくなります。是非これからもこのような素敵なアクリルケースを楽しみにしております。また注文させて頂きますね。',5,NULL,NULL,'*.dion.ne.jp',NULL,'90',1,NULL,NULL,'2012-09-12 15:00:00','2012-09-12 15:00:00'),(5244,'箱型アクリルケース',NULL,NULL,NULL,NULL,'KAZ',NULL,'新社屋の模型の展示をロビーで始めました。ケースに入れることで注目度が上がり社員の関心も非常に高くなりました。ありがとうございました。',5,NULL,NULL,'*.dion.ne.jp',NULL,'91',1,NULL,NULL,'2012-09-13 15:00:00','2012-09-13 15:00:00'),(5245,'箱型アクリルケース',NULL,NULL,NULL,NULL,'AAA',NULL,'しっかりした作りで満足しています。',4,NULL,NULL,'*.nttpc.ne.jp',NULL,'92',1,NULL,NULL,'2012-09-13 15:00:00','2012-09-13 15:00:00'),(5246,'箱型アクリルケース',NULL,NULL,NULL,NULL,'H.I',NULL,'迅速な対応と丁寧な仕事で安心しました。WEB上で見積もりがはっきり出るのがうれしいです。',5,NULL,NULL,'*.icnet.ne.jp',NULL,'93',1,NULL,NULL,'2012-09-13 15:00:00','2012-09-13 15:00:00'),(5247,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'ぽんぽん',NULL,'大変いい商品でした。また、納品も非常に早かったです。ありがとうございました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'94',1,NULL,NULL,'2012-09-14 15:00:00','2012-09-14 15:00:00'),(5248,'ディスプレイスタンド',NULL,NULL,NULL,NULL,'東京都　M.I',NULL,'最初、自作しようかとも思ったのですが、プロにまかせて正解でした。少々お値段は張りますが、仕上がりの綺麗さと短時間で手にできるので納得です。パンフレット置きとして使用していますが、今まで雑然としてたのが、すっきりと美しく整理整頓できたので満足しています。',5,NULL,NULL,'*.dy.bbexcite.jp',NULL,'95',1,NULL,NULL,'2012-09-14 15:00:00','2012-09-14 15:00:00'),(5249,'箱型アクリルケース',NULL,NULL,NULL,NULL,'ごうち',NULL,'値段も手頃で仕上がりも綺麗でした、またお願いしようかと思います。寸法指定でしたが納期も早かったです。',5,NULL,NULL,'61.120.94.209',NULL,'96',1,NULL,NULL,'2012-09-14 15:00:00','2012-09-14 15:00:00'),(5250,'アクリルコレクションケース',NULL,NULL,NULL,NULL,'黒雪姫',NULL,'とても満足です。',5,NULL,NULL,'*.spmode.ne.jp',NULL,'97',1,NULL,NULL,'2012-09-15 15:00:00','2012-09-15 15:00:00'),(5251,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'Yosi',NULL,'きっちりとした対応で安心して任せられました。アクリル封入も見事でさっそく飾っております。ありがとうございました。',5,NULL,NULL,'*.bbtec.net',NULL,'98',1,NULL,NULL,'2012-09-15 15:00:00','2012-09-15 15:00:00'),(5252,'アクリルコレクションケース',NULL,NULL,NULL,NULL,'お客さん',NULL,'初めて利用させてもらいましたが、セミオーダーで希望通りの商品で満足です。',5,NULL,NULL,'*.plala.or.jp',NULL,'99',1,NULL,NULL,'2012-09-15 15:00:00','2012-09-15 15:00:00'),(5253,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'jk',NULL,'商品の注文違いで、返品、交換対応していただいたのですが、送料、こちら持で手数料1500円も取るのは、たかが交換では、高過ぎると思います。どういう理由でこの金額なのかお聞かせ願いたい。交換した商品も、穴の位置が微妙にズレていて、ネジがはめずらかったです。',2,NULL,NULL,'*.home.ne.jp',NULL,'100',1,NULL,NULL,'2012-09-15 15:00:00','2012-09-15 15:00:00'),(5254,'アクリル押出板',NULL,NULL,NULL,NULL,'GONTA',NULL,'何度か利用させて頂いていますが、正確な製品が短納期で届く点が良いです。とても助かります。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'101',1,NULL,NULL,'2012-09-10 15:00:00','2012-09-10 15:00:00'),(5255,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'こんちゃん',NULL,'フルオーダー加工品でしたが、精度も良く問題なく使用できております。',5,NULL,NULL,'*.fch.ne.jp',NULL,'102',1,NULL,NULL,'2012-09-16 15:00:00','2012-09-16 15:00:00'),(5256,'アクリル オープンボックス セミオーダー',NULL,NULL,NULL,NULL,'千葉　tawako',NULL,'棚の中のムダな空間にもう一つの棚ができて、収納量が増えました。アクリルの色はオパールで厚さは５ミリなので圧迫感もなく使いやすいです。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'103',1,NULL,NULL,'2012-09-16 15:00:00','2012-09-16 15:00:00'),(5257,'アクリルパイプ/丸棒加工　セミオーダー',NULL,NULL,NULL,NULL,'沖縄H.R',NULL,'商品の配送がスムーズでした。梱包も丁寧です。',5,NULL,NULL,'*.panda-world.ne.jp',NULL,'104',1,NULL,NULL,'2012-09-16 15:00:00','2012-09-16 15:00:00'),(5258,'ガラス蝶番',NULL,NULL,NULL,NULL,'埼玉県 YP',NULL,'常々、あったらいいなと思ってたいた商品がこのサイトにありました。素人の私でも簡単に加工ができました。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'105',1,NULL,NULL,'2012-09-16 15:00:00','2012-09-16 15:00:00'),(5259,'アクリル押出板',NULL,NULL,NULL,NULL,'ｃｆｃ',NULL,'早いですねー、早くて採寸どおりなので感激しました、ありがとうございました、機会がありまあしたら、またお願いします。',5,NULL,NULL,'*.plala.or.jp',NULL,'106',1,NULL,NULL,'2012-09-15 15:00:00','2012-09-15 15:00:00'),(5260,'アクリル押出板',NULL,NULL,NULL,NULL,'leo',NULL,'期待通りの商品で満足しています。',5,NULL,NULL,'*.bbtec.net',NULL,'107',1,NULL,NULL,'2012-09-16 15:00:00','2012-09-16 15:00:00'),(5261,'箱型アクリルケース',NULL,NULL,NULL,NULL,'Sun',NULL,'商品を細かく設定でき、理想のものが購入できたので良かったです。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'108',1,NULL,NULL,'2012-09-17 15:00:00','2012-09-17 15:00:00'),(5262,'アクリル押出板',NULL,NULL,NULL,NULL,'Yacco',NULL,'対応が早いのでいつも助かっています。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'109',1,NULL,NULL,'2012-09-17 15:00:00','2012-09-17 15:00:00'),(5263,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'水玉ハト',NULL,'迅速に届き、助かりました。A2サイズを購入しましたが、大きさの割に軽くて運びやすいです。保護紙をとったあとの静電気がすごいので、清潔な環境で組み立てたほうが良いです。',5,NULL,NULL,'*.ucatv.ne.jp',NULL,'110',1,NULL,NULL,'2012-09-19 15:00:00','2012-09-19 15:00:00'),(5264,'液晶テレビ保護パネルＬ型　セミオーダー',NULL,NULL,NULL,NULL,'ﾃﾚﾋﾞ保護',NULL,'寸法特注で取付けました。テレビの下隅の角をＲ加工を頼めば（頼むことが出来れば）もっと良かったです。（現在はウレタンの角保護材を貼付）ノングレアにするか迷いましたが、蛍光灯の光がまともに反射している場所だったので、多少高くてもノングレアタイプで正解でした。　（蛍光灯の光はほとんど気になりません）',4,NULL,NULL,'218.224.235.147',NULL,'111',1,NULL,NULL,'2012-09-19 15:00:00','2012-09-19 15:00:00'),(5265,'ユニフォーム額',NULL,NULL,NULL,NULL,'もりし',NULL,'ユニホームの額を購入しました。納得いくもので満足しています',4,NULL,NULL,'*.eonet.ne.jp',NULL,'112',1,NULL,NULL,'2012-09-19 15:00:00','2012-09-19 15:00:00'),(5266,'箱型アクリルケース',NULL,NULL,NULL,NULL,'alice',NULL,'オーダーでアクリルボックスをお願いしました。とてもきれいにできていていつも満足しております。オーダーのページも初めての方でもとてもわかりやすく使いやすいですね。スムーズにオーダーできるシステムも気に入ってます。いつも丁寧に対応していただいて本当に感謝しております。',5,NULL,NULL,'*.plala.or.jp',NULL,'113',1,NULL,NULL,'2012-09-20 15:00:00','2012-09-20 15:00:00'),(5267,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'TK',NULL,'大変満足しています。',4,NULL,NULL,'*.panda-world.ne.jp',NULL,'114',1,NULL,NULL,'2012-09-20 15:00:00','2012-09-20 15:00:00'),(5268,'箱型アクリルケース',NULL,NULL,NULL,NULL,'まーちゃん',NULL,'特になし',4,NULL,NULL,'*.bbtec.net',NULL,'115',1,NULL,NULL,'2012-09-20 15:00:00','2012-09-20 15:00:00'),(5269,'ディスプレイラック　セミオーダー',NULL,NULL,NULL,NULL,'モモママ',NULL,'作品を作るための材料をおくために購入いたしました。とてもきれいな仕上がりでお値段も安く、他社にはないと思いました。またぜひ、お願いしたいと思います。',5,NULL,NULL,'*.home.ne.jp',NULL,'116',1,NULL,NULL,'2012-09-20 15:00:00','2012-09-20 15:00:00'),(5270,'アクリル押出板',NULL,NULL,NULL,NULL,'tactacpooh',NULL,'アクリルの加工は初めてでしたが、意外に簡単にできました。ただ、接着剤がサラサラしていたので、垂らしたところがちょっと跡が残りました。でも息子の自由研究（工作）のケースが素晴らしいものになりました。ありがとうございました。　※「当日出荷予約済み」の”ステップ”があることに気付かず、ご迷惑をおかけいたしました。（電話かネットで予約すると勘違いしていました。）次回はきちんと電話してから注文いたします。またよろしくお願いします。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'117',1,NULL,NULL,'2012-09-18 15:00:00','2012-09-18 15:00:00'),(5271,'アクリル押出板',NULL,NULL,NULL,NULL,'ろしなんて',NULL,'アクリル板は初めて購入しましたが、梱包もしっかりしていて感心しました。',5,NULL,NULL,'*.tachikawa.mopera.net',NULL,'118',1,NULL,NULL,'2012-09-20 15:00:00','2012-09-20 15:00:00'),(5272,'アクリル押出板',NULL,NULL,NULL,NULL,'アンクルマン',NULL,'風呂と炊事場のガラス交換をＤＩＹで行いました。某ＨＰで素人にガラスの場合は危うい？と書き込みしてあったのでアクリル板でチャレンジ。価格も御社ではありませんが、同価格でした。交換は、初めてでしたけどスムーズにいけました。両面つや消しを選択しましたが本当は片面つや消しが希望でした。静電気でホコリが心配でしたが驚くほど付きません。炊事場もＩＨなので耐火性も余り気にしていません。自分も、家内も大満足です。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'119',1,NULL,NULL,'2012-09-21 15:00:00','2012-09-21 15:00:00'),(5273,'箱型アクリルケース',NULL,NULL,NULL,NULL,'M.N',NULL,'今回で2回目の注文させて頂きました。欲しいサイズのケースが見つからなかった時に御社のホームページを見つけて注文させて頂きました。今回は親に頼まれケース注文させて頂きました。とても丁寧で綺麗な出来で満足しています。また必要になった時にお願いさせて頂きたいと思います。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'120',1,NULL,NULL,'2012-09-22 15:00:00','2012-09-22 15:00:00'),(5274,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'やました',NULL,'入力した値が図面として描かれ大変わかりやすく素人でも発注できて良いと思います',5,NULL,NULL,'*.so-net.ne.jp',NULL,'121',1,NULL,NULL,'2012-09-22 15:00:00','2012-09-22 15:00:00'),(5275,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'ｔｍ',NULL,'角抜き加工の内角はｒ無しの直角加工も有ると良いと思います。',4,NULL,NULL,'*.spmode.ne.jp',NULL,'122',1,NULL,NULL,'2012-09-23 15:00:00','2012-09-23 15:00:00'),(5276,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'SN',NULL,'寸法の精度が良く。大変満足です。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'123',1,NULL,NULL,'2012-09-23 15:00:00','2012-09-23 15:00:00'),(5277,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'生技のみかた',NULL,'外形寸法が500mmを超えるサイズで、手作業での加工が困難なこともあって、磨き仕上げでの注文だったので、後の作業が楽にできました。',4,NULL,NULL,'*.iwamicatv.jp',NULL,'124',1,NULL,NULL,'2012-09-23 15:00:00','2012-09-23 15:00:00'),(5278,'カタログケース屋外用　ステン蝶番タイプ',NULL,NULL,NULL,NULL,'M',NULL,'作りが綺麗で、仕上げも綺麗です。価格も高すぎず、適正な範囲だと思います。',5,NULL,NULL,'*.mitene.or.jp',NULL,'125',1,NULL,NULL,'2012-09-23 15:00:00','2012-09-23 15:00:00'),(5279,'アクリル押出板',NULL,NULL,NULL,NULL,'神奈川県YK',NULL,'机の天板で注文ですが、大変満足です。',5,NULL,NULL,'*.e-mobile.ne.jp',NULL,'126',1,NULL,NULL,'2012-09-21 15:00:00','2012-09-21 15:00:00'),(5280,'アクリル押出板',NULL,NULL,NULL,NULL,'やっくん',NULL,'冷蔵庫の棚が破損してしまったため、その代わりにとアクリル板を注文しました。５mmで十分かと思いましたが、実際使ってみると冷蔵庫には液体やビンカンなど意外と思い物をいれるので、ややたわみました。アクリルの厚さと、重さに対するたわみ具合が写真でわかるようになっていたら、より適切な物を選びやすいと思いました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'127',1,NULL,NULL,'2012-09-23 15:00:00','2012-09-23 15:00:00'),(5281,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'くまさん',NULL,'設備・装置の防塵用に使用しました。既製品を切断する手間と仕上がり状態を比べると納期も早く、価格も加工費込みで割安です。作業持間の大きな削減に繋がりました。',4,NULL,NULL,'*.chukai.ne.jp',NULL,'128',1,NULL,NULL,'2012-09-24 15:00:00','2012-09-24 15:00:00'),(5282,'アクリル押出板',NULL,NULL,NULL,NULL,'kaiba',NULL,'アクリルカッターの刃はこまめに交換すること！',5,NULL,NULL,'*.so-net.ne.jp',NULL,'129',1,NULL,NULL,'2012-09-24 15:00:00','2012-09-24 15:00:00'),(5283,'油彩キャンバス立体額',NULL,NULL,NULL,NULL,'Tokyo J.K',NULL,'キャンバスの0号などの別の規格も是非商品ラインナップにして頂きたいです。',4,NULL,NULL,'*.dion.ne.jp',NULL,'130',1,NULL,NULL,'2012-09-24 15:00:00','2012-09-24 15:00:00'),(5284,'アクリル押出板',NULL,NULL,NULL,NULL,'ST',NULL,'納期短縮をお願いし、すばやく対応いただきました。大変助かりました。',4,NULL,NULL,'*.jp.panasonic.com',NULL,'131',1,NULL,NULL,'2012-09-24 15:00:00','2012-09-24 15:00:00'),(5285,'アクリルテーブル',NULL,NULL,NULL,NULL,'むさし',NULL,'予定どうりの出来上がりで満足です。',4,NULL,NULL,'*.so-net.ne.jp',NULL,'132',1,NULL,NULL,'2012-09-27 15:00:00','2012-09-27 15:00:00'),(5286,'ディスプレイラック　セミオーダー',NULL,NULL,NULL,NULL,'SK',NULL,'出窓に置くための小形のアクリル棚をオーダーでお願いしました。望んでいた通りのもので、大変満足しております。',5,NULL,NULL,'*.dion.ne.jp',NULL,'133',1,NULL,NULL,'2012-09-28 15:00:00','2012-09-28 15:00:00'),(5287,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'J Rose',NULL,'精巧で清潔感のあるケースを作っていただき満足しています。',5,NULL,NULL,'*.bbtec.net',NULL,'134',1,NULL,NULL,'2012-09-29 15:00:00','2012-09-29 15:00:00'),(5288,'箱型アクリルケース',NULL,NULL,NULL,NULL,'ASH',NULL,'セミオーダーで注文したのですが、注文して１週間もかからずに到着しました。やはり専門業者様だけあって精度や品質が非常に高く、今回のアクリルケースもディスプレイの一部として雰囲気作りに一役買っています。また、一つ要望となりますが、セミオーダーの際におおよその重量も表示して頂けると助かります。（飾り場所の積載可能重量に対する判断に使用します。）それではまた利用させて頂きますので、宜しくお願い致します。',5,NULL,NULL,'*.home.ne.jp',NULL,'135',1,NULL,NULL,'2012-09-29 15:00:00','2012-09-29 15:00:00'),(5289,'アクリル押出板',NULL,NULL,NULL,NULL,'max',NULL,'今回座卓にはめこむために初めてガラス色を使ったのですが見た目に重みがでて落ち着いた良い感じになり透明な板よりも全然良かったです。又輸送時の梱包もしっかりしていて満足していますが、注文から納品までがもう少し早ければありがたいです。',5,NULL,NULL,'116.193.97.121',NULL,'136',1,NULL,NULL,'2012-09-27 15:00:00','2012-09-27 15:00:00'),(5290,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'ぷるちゃん',NULL,'初めて注文したのですが、スムーズな対応いただきまして安心して手続きが進められました。ありがとうございます。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'137',1,NULL,NULL,'2012-09-30 15:00:00','2012-09-30 15:00:00'),(5291,'アクリル押出板',NULL,NULL,NULL,NULL,'cool',NULL,'商品発注から納品までスムーズでした。基本的なことですが、ひとつひとつの対応がしっかりしているので安心しました。もちろん商品もバッチリでした。',4,NULL,NULL,'*.biz.bbtec.net',NULL,'138',1,NULL,NULL,'2012-09-30 15:00:00','2012-09-30 15:00:00'),(5292,'アクリサンデー　ミラー調スプレー',NULL,NULL,NULL,NULL,'moo',NULL,'発送手配が素早くとても満足しています。ところでこちらのホームページはとても素晴らしいですね。アクリル加工が初めてだったのですが、ホームページを参考にして簡単に綺麗に完成させることが出来ました。ホームページが充実しているので助かりました。ありがとうございました。',4,NULL,NULL,'*.nttpc.ne.jp',NULL,'139',1,NULL,NULL,'2012-10-03 15:00:00','2012-10-03 15:00:00'),(5293,'フォトフレーム　スタンダード',NULL,NULL,NULL,NULL,'morimorige',NULL,'いつもいい物有難うございます。',5,NULL,NULL,'*.plala.or.jp',NULL,'140',1,NULL,NULL,'2012-10-03 15:00:00','2012-10-03 15:00:00'),(5294,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'ICCSPS',NULL,'注文加工を手軽にできるので、助かります。',4,NULL,NULL,'*.odn.ne.jp',NULL,'141',1,NULL,NULL,'2012-10-03 15:00:00','2012-10-03 15:00:00'),(5295,'アクリル端材（薄板・厚板）',NULL,NULL,NULL,NULL,'peppeppep',NULL,'想像通りの出来栄えでした',4,NULL,NULL,'*.sekisui.jp',NULL,'142',1,NULL,NULL,'2012-10-04 15:00:00','2012-10-04 15:00:00'),(5296,'アクリル押出板',NULL,NULL,NULL,NULL,'maru',NULL,'大変きれいで満足です。UVインキジェットで看板を作りました。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'143',1,NULL,NULL,'2012-10-03 15:00:00','2012-10-03 15:00:00'),(5297,'アクリル押出板',NULL,NULL,NULL,NULL,'コーチャン',NULL,'カットも良く満足でした、　出来る事ならカットの端材がどの位でき端材が適当であれば欲しいと思います',4,NULL,NULL,'*.ocn.ne.jp',NULL,'144',1,NULL,NULL,'2012-10-04 15:00:00','2012-10-04 15:00:00'),(5298,'アクリル押出板',NULL,NULL,NULL,NULL,'べ',NULL,'サイズが幅広く選べるので良い',4,NULL,NULL,'*.ocn.ne.jp',NULL,'145',1,NULL,NULL,'2012-10-04 15:00:00','2012-10-04 15:00:00'),(5299,'アクリルコレクションケース',NULL,NULL,NULL,NULL,'gen',NULL,'予想を遥かに超える出来で非常に満足。注文時にカット面の項目が無かったので不安でしたが、しっかりと磨き上げ加工なので安心しました。フィギュアを飾る為に注文したので土台になるスタンドも一緒に欲しかったのですが3点セット販売なので諦めました、出来ればバラで売ってもらえると助かります。今後アクリル用品が必要ならまた頼むと思います。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'146',1,NULL,NULL,'2012-10-04 15:00:00','2012-10-04 15:00:00'),(5300,'ポリカーボネート板',NULL,NULL,NULL,NULL,'べこー',NULL,'迅速に対応され感謝しています。',5,NULL,NULL,'*.t-net.ne.jp',NULL,'147',1,NULL,NULL,'2012-10-05 15:00:00','2012-10-05 15:00:00'),(5301,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'あきひろ',NULL,'フルオーダーで3面にイラストやテキストを刻印したボックス（5面体）を作成いただきました。透明なアクリルに浮かび上がるイラストは想像以上の仕上がりで満足しております。また利用させていただきたいと思います。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'148',1,NULL,NULL,'2012-10-05 15:00:00','2012-10-05 15:00:00'),(5302,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'きむきむ',NULL,'アクリル板で、熱帯魚水槽のふたをオーダーしました。ベタは飛び出しの危険があるため隙間のないぴったりのものがほしかったんです。餌をあげる時だけの穴にはふたも必要で。素人のつたない図面をもとに想像以上の出来上がりで感謝しています。しかもデザインは希望のものと変えずふたの構造を使い勝手の良いものに変更してくださり、心使いにおどろきました。ありがとうございました。',5,NULL,NULL,'*.canvas.ne.jp',NULL,'149',1,NULL,NULL,'2012-10-05 15:00:00','2012-10-05 15:00:00'),(5303,'アクリル押出板',NULL,NULL,NULL,NULL,'BRA550',NULL,'納期まで２週間と少々長めでしたが、待った甲斐がありました。こちらの指示通りのものがもの凄いクオリティで仕上がってきました。',5,NULL,NULL,'*.bbtec.net',NULL,'150',1,NULL,NULL,'2012-10-04 15:00:00','2012-10-04 15:00:00'),(5304,'アクリル厚板',NULL,NULL,NULL,NULL,'ヤスリン',NULL,'とてもいい出来栄えです',4,NULL,NULL,'*.plala.or.jp',NULL,'151',1,NULL,NULL,'2012-10-05 15:00:00','2012-10-05 15:00:00'),(5305,'アクリル押出板',NULL,NULL,NULL,NULL,'宇宙ＷＡＳＡＢＩ',NULL,'とても良かったです…がアクリルのマットのカラー少ないのと、実際に店舗に出向いて商品に触れてから購入をしてみたい。',3,NULL,NULL,'*.sannet.ne.jp',NULL,'152',1,NULL,NULL,'2012-10-05 15:00:00','2012-10-05 15:00:00'),(5306,'箱型アクリルケース',NULL,NULL,NULL,NULL,'king',NULL,'いつもとうり正確な寸法できれいな仕上がりでした。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'153',1,NULL,NULL,'2012-10-07 15:00:00','2012-10-07 15:00:00'),(5307,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'おしん',NULL,'きれいに仕上がり喜んでいます。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'154',1,NULL,NULL,'2012-10-07 15:00:00','2012-10-07 15:00:00'),(5308,'アクリルドーム（半球）　射出成形品',NULL,NULL,NULL,NULL,'があくん',NULL,'半球を球にして使用するのですが、精度が良くできているので全く問題ありませんでした。',4,NULL,NULL,'*.bf.2iij.net',NULL,'155',1,NULL,NULL,'2012-10-07 15:00:00','2012-10-07 15:00:00'),(5309,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'toshiy',NULL,'仕上がりは満足いくものでした。クリアー以外にも板厚の厚いものがあればと思います。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'156',1,NULL,NULL,'2012-10-07 15:00:00','2012-10-07 15:00:00'),(5310,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'らんたろう',NULL,'初めて、利用させて頂きました。加工・配送は早かったです。出来れば、料金を安く出来ればと・・・・',5,NULL,NULL,'*.ocn.ne.jp',NULL,'157',1,NULL,NULL,'2012-10-08 15:00:00','2012-10-08 15:00:00'),(5311,'ガルウイングケース',NULL,NULL,NULL,NULL,'xiu　',NULL,'セガトイズのグランドピアニストを入れるために特注で購入。キズ、ホコリの心配もなくなり、またセガのオリジナルケースより五センチ大きいので余裕で椅子に人形を座らせることができました。よく話題になる鍵盤のガチャガチャ音もほとんど聞こえなくなり、ウィングケースのためスイッチの開閉、SDカードの交換も容易で大変満足しております。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'158',1,NULL,NULL,'2012-10-08 15:00:00','2012-10-08 15:00:00'),(5312,'箱型アクリルケース',NULL,NULL,NULL,NULL,'snow',NULL,'前回はけんどん式の大きなサイズを注文させて頂いたのですが、その時の商品の完成度が非常に素晴らしく、今回は以前からフィギュア用として購入検討していた小さめサイズのケースを注文させて頂きました。それで先日届いたのですが、やはりアクリ屋様の商品は大変質感が良く、想定していた通りのお品になっておりました。サイズもフィギュアにちょうど合っていて、カポッと被せたらぴったりでした。本当にいつもありがとうございます。また機会がございましたら、注文させて頂きたいと思いますので、その時には宜しくお願い致します。',5,NULL,NULL,'*.dion.ne.jp',NULL,'159',1,NULL,NULL,'2012-10-07 15:00:00','2012-10-07 15:00:00'),(5313,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'S',NULL,'丸型アクリル板を購入しました。とても重宝しています。リピしました。',5,NULL,NULL,'*.kcn.ne.jp',NULL,'160',1,NULL,NULL,'2012-10-08 15:00:00','2012-10-08 15:00:00'),(5314,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'雅子様',NULL,'発送も早く迅速な対応に満足しています。アクリル板も一流メーカーのもので高品質、もっとペラペラな物を想像していましたが思ったより丈夫で驚きました。セミオーダーで思い通りの商品を提供していただけるのも便利ですね。',5,NULL,NULL,'*.dti.ne.jp',NULL,'161',1,NULL,NULL,'2012-10-09 15:00:00','2012-10-09 15:00:00'),(5315,'油彩キャンバス立体額',NULL,NULL,NULL,NULL,'ニックネーム',NULL,'セミオーダーだとまず見積もりをしてもらわないといけない所が多いですが、こちらはHP上で値段がわかるので注文しやすいです。額なので商品がちょうど入るダンボールに入って届くと勝手に思っていたのですが無くて残念です。',4,NULL,NULL,'*.gctv.ne.jp',NULL,'162',1,NULL,NULL,'2012-10-09 15:00:00','2012-10-09 15:00:00'),(5316,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'静岡県 のり',NULL,'グレースモーク色を注文しました。ほとんど透過しないのかと思っていましたが予想より見えるんですね。次はブラックで注文しようと思います。製品自体はは大満足です。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'163',1,NULL,NULL,'2012-10-10 15:00:00','2012-10-10 15:00:00'),(5317,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'良太',NULL,'大変満足しております。今後、社内各担当者に紹介し推奨するようにいたします。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'164',1,NULL,NULL,'2012-10-10 15:00:00','2012-10-10 15:00:00'),(5318,'アクリル押出板',NULL,NULL,NULL,NULL,'山口',NULL,'いつも通り、素早い対応をありがとうございます。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'165',1,NULL,NULL,'2012-10-08 15:00:00','2012-10-08 15:00:00'),(5319,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'mNEFO',NULL,'今回はアクリル5mm厚でロの字状に接着したケースを特注しました。形状的にはほぼ満足ですが、端面に一部段差がありました。公差内なので致し方ありませんが、できれば端面は揃えてほしかったです。',4,NULL,NULL,'*.vectant.ne.jp',NULL,'166',1,NULL,NULL,'2012-10-11 15:00:00','2012-10-11 15:00:00'),(5320,'アクリル接着剤用　注射器',NULL,NULL,NULL,NULL,'せんちゃん',NULL,'とても丁寧な包装でよかったです又接着剤に使う注射器がとても助かりましたそのために素敵なジオラマケースができました。ありがとうございました。またの機会にもよろしくお願いいたします。北野',5,NULL,NULL,'*.ocn.ne.jp',NULL,'167',1,NULL,NULL,'2012-10-11 15:00:00','2012-10-11 15:00:00'),(5321,'箱型アクリルケース',NULL,NULL,NULL,NULL,'r',NULL,'UVカット効果があるコレクションケースをセミオーダーできるのと、納品がとにかく早いのが非常に助かります。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'168',1,NULL,NULL,'2012-10-11 15:00:00','2012-10-11 15:00:00'),(5322,'アクリル集光板',NULL,NULL,NULL,NULL,'H',NULL,'楽しい素材です。　無限の可能性というか、創意工夫のモトになります。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'169',1,NULL,NULL,'2012-10-13 15:00:00','2012-10-13 15:00:00'),(5323,'LUPIKA（ルピカ）',NULL,NULL,NULL,NULL,'inakamono',NULL,'LUPIKA（ルピカ）をセット購入させていただき、工作しました。０*//正直、LED製の台は若干、値段が高く感じますがよく出来ています。欲を言えばSMDのLEDが４点６点点灯したら良いなと思いました。あとできればひな形の図案などあれば便利なのですが、、、アクリ屋ドットコムはスタッフさんがブログなどでいろんな手法やQ&Aなどもあり、ビギナーには大変助かります。',4,NULL,NULL,'*.ocn.ne.jp',NULL,'170',1,NULL,NULL,'2012-10-14 15:00:00','2012-10-14 15:00:00'),(5324,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'headway',NULL,'価格、対応、納期については満足です。納期は積極的な前倒しが成されて結果的には大変ありがたいのですが、納期マージンの考慮しすぎが少し気になるところでした。',5,NULL,NULL,'124.35.2.74',NULL,'171',1,NULL,NULL,'2012-10-14 15:00:00','2012-10-14 15:00:00'),(5325,'アクリル押出板',NULL,NULL,NULL,NULL,'hiyo',NULL,'サイズもピッタリで、ホコリも付かず。ガラスの書棚に違和感なく取り付けられた。これからも、ガラスが割れた時の代用として、使いたい',4,NULL,NULL,'*.infoweb.ne.jp',NULL,'172',1,NULL,NULL,'2012-10-11 15:00:00','2012-10-11 15:00:00'),(5326,'アクリル押出板',NULL,NULL,NULL,NULL,'haya',NULL,'特になし',4,NULL,NULL,'*.ocn.ne.jp',NULL,'173',1,NULL,NULL,'2012-10-14 15:00:00','2012-10-14 15:00:00'),(5327,'アクリル押出板',NULL,NULL,NULL,NULL,'itohka',NULL,'大変きれいに出来ていました。',5,NULL,NULL,'*.bbtec.net',NULL,'174',1,NULL,NULL,'2012-10-14 15:00:00','2012-10-14 15:00:00'),(5328,'箱型アクリルケース',NULL,NULL,NULL,NULL,'名無',NULL,'予定納期より早く出荷してもらえたので驚きました。機会があればまた利用したいです。',5,NULL,NULL,'*.megaegg.ne.jp',NULL,'175',1,NULL,NULL,'2012-10-14 15:00:00','2012-10-14 15:00:00'),(5329,'アクリル型模様板',NULL,NULL,NULL,NULL,'KOS21',NULL,'短納期、高品質でのご提供ありがとうございます。',4,NULL,NULL,'*.dion.ne.jp',NULL,'176',1,NULL,NULL,'2012-10-15 15:00:00','2012-10-15 15:00:00'),(5330,'アクリル押出板',NULL,NULL,NULL,NULL,'せきちゃん',NULL,'オーダーサイズのアクリル板を購入しました。0.5mm単位でのオーダーが出来非常に助かりました。精度も良く満足しております。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'177',1,NULL,NULL,'2012-10-14 15:00:00','2012-10-14 15:00:00'),(5331,'アクリル押出板',NULL,NULL,NULL,NULL,'NT富山',NULL,'今回初めての利用でした。納期等特に問題ありませんが、オーダー量が少ないこともあり、非常に良いとも判断できなかったので、”良い”とさせていただきました。今後も機会があれば利用させていただきます。',4,NULL,NULL,'*.nec.co.jp',NULL,'178',1,NULL,NULL,'2012-10-16 15:00:00','2012-10-16 15:00:00'),(5332,'アクリル押出板',NULL,NULL,NULL,NULL,'みねぼー',NULL,'とても綺麗でした、梱包も二重にしてあり傷一つありません、お安く購入出来ました、ありがとうございました、グランドピアノフロントフレームカバーに使おうと思っています、3mmでよかった気がします、（まだ使用してませんが）・・',5,NULL,NULL,'*.ocn.ne.jp',NULL,'179',1,NULL,NULL,'2012-10-18 15:00:00','2012-10-18 15:00:00'),(5333,'アクリル集光板',NULL,NULL,NULL,NULL,'H',NULL,'アクリル集光板は面白い素材です。　装飾目的だけでは勿体無い素材ではあります。　価格ですが、もう少し安いとありがたいのですが、、、',5,NULL,NULL,'*.ocn.ne.jp',NULL,'180',1,NULL,NULL,'2012-10-19 15:00:00','2012-10-19 15:00:00'),(5334,'色紙額',NULL,NULL,NULL,NULL,'りえぞう',NULL,'UV面の説明がちょっととまどいました。加工されていない方のアクリル板に「赤または青（？）の線」があったので。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'181',1,NULL,NULL,'2012-10-19 15:00:00','2012-10-19 15:00:00'),(5335,'箱型アクリルケース',NULL,NULL,NULL,NULL,'marina',NULL,'いつも重宝しています。私が発注した同業者様の中で仕上げも一番正確できれいですし梱包も丁寧にお届けいただいていると思います。直接の問い合わせにも迅速なご対応いただき気持ちのよいお取引をいただいています。',5,NULL,NULL,'*.plala.or.jp',NULL,'182',1,NULL,NULL,'2012-10-19 15:00:00','2012-10-19 15:00:00'),(5336,'ポリカーボネート板',NULL,NULL,NULL,NULL,'zen',NULL,'納期も早かったので割と満足しています。',3,NULL,NULL,'*.ocn.ne.jp',NULL,'183',1,NULL,NULL,'2012-10-19 15:00:00','2012-10-19 15:00:00'),(5337,'箱型アクリルケース',NULL,NULL,NULL,NULL,'三橋弘宗',NULL,'公費支払（地方自治体の機関なので）や法人払いできるようにしていただきたい。',4,NULL,NULL,'*.hitohaku.jp',NULL,'184',1,NULL,NULL,'2012-10-20 15:00:00','2012-10-20 15:00:00'),(5338,'アクリル押出板',NULL,NULL,NULL,NULL,'ジム',NULL,'希望通りの商品が届きました。今回は３回目の発注でしたが納期、梱包状態とも良好で品質も問題ありませんでした。アクリル屋さんの所在地が港北区で我が家から近く近親間もあり何かと便利なので再々発注いたしました。お陰様で二重窓工事も無事完了いたしました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'185',1,NULL,NULL,'2012-10-18 15:00:00','2012-10-18 15:00:00'),(5339,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'s',NULL,'装飾のある台には、とてもすぐれものです。',5,NULL,NULL,'*.kcn.ne.jp',NULL,'186',1,NULL,NULL,'2012-10-20 15:00:00','2012-10-20 15:00:00'),(5340,'アクリルパイプ/丸棒加工　セミオーダー',NULL,NULL,NULL,NULL,'さちお',NULL,'製品満足しております。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'187',1,NULL,NULL,'2012-10-20 15:00:00','2012-10-20 15:00:00'),(5341,'アクリル押出板',NULL,NULL,NULL,NULL,'コルセア',NULL,'　コレクションボードの棚板として使用するため、長年ホームセンター等でアクリル板を探していました。　ホームセンターはもとより、アクリル板の取り扱い店においても、サイズ（希望サイズのカットを含め）等希望に合うものはありませんでした。　しかし、今回ネット上で御社を見つけ、希望通りのアクリル板を入手する事が出来ました。　ネット上で即見積も出来ましたし、注文に対する対応も早く、また、現物も想像を超えるすばらしいもので非常に満足しております。　また購入したいと思っています。　　',5,NULL,NULL,'*.ocn.ne.jp',NULL,'188',1,NULL,NULL,'2012-10-20 15:00:00','2012-10-20 15:00:00'),(5342,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'なみ',NULL,'リピーターですが、とっても素晴らしい商品なので安心して注文しています。梱包も的確で最高です。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'189',1,NULL,NULL,'2012-10-21 15:00:00','2012-10-21 15:00:00'),(5343,'アクリルハードコート（耐擦傷）板',NULL,NULL,NULL,NULL,'きらーん',NULL,'きれいにしあがっており満足しております。また、お願いしたいと思います。',5,NULL,NULL,'118.159.235.133',NULL,'190',1,NULL,NULL,'2012-10-21 15:00:00','2012-10-21 15:00:00'),(5344,'アクリル押出板',NULL,NULL,NULL,NULL,'クーサン',NULL,'単純な商品なので特にありません。指定の物が無事届きました。',5,NULL,NULL,'*.uqwimax.jp',NULL,'191',1,NULL,NULL,'2012-10-20 15:00:00','2012-10-20 15:00:00'),(5345,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'taishou',NULL,'アクリル板カット、セミオーダーを発注しましたが、きっちりと精度よくカットしているので助かります。欲を言えば、切り欠き等にも対応して頂けると助かります。',5,NULL,NULL,'*.lion.co.jp',NULL,'192',1,NULL,NULL,'2012-10-21 15:00:00','2012-10-21 15:00:00'),(5346,'フォトフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'か',NULL,'単価が高い。20と50個の間にも割引率の差が欲しい。',4,NULL,NULL,'219.163.150.193',NULL,'193',1,NULL,NULL,'2012-10-21 15:00:00','2012-10-21 15:00:00'),(5347,'アクリル押出板',NULL,NULL,NULL,NULL,'VIC',NULL,'いつも迅速な良い対応をしていただきありがとうございます。商品はとても丁寧に梱包されていて安心して注文できます。但し、梱包を解く際に困っていることがあります。透明のクッション材（プチプチ？）を貼り付けている透明のセロテープの位置が解らずはぎ取るのに時間がかかることです。貼り付けるテープに少し色を付けてあるととても良いのですが。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'194',1,NULL,NULL,'2012-10-21 15:00:00','2012-10-21 15:00:00'),(5348,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'匿名',NULL,'船舶用エンジン部品の交換材料としてアクリル材の８ｍｍ円板をオーダーしました。海水が入るところの点検窓で、ひびが入っていたり、くすんでしまっていたため交換しましたが、とてもクリアになり満足です。もともと付いている円板が７．５ｍｍ厚のため同サイズが欲しかったので、厚み指定ができればよかったです。',5,NULL,NULL,'*.ucom.ne.jp',NULL,'195',1,NULL,NULL,'2012-10-22 15:00:00','2012-10-22 15:00:00'),(5349,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'北海道　Kopi-h',NULL,'板の斜めカットでの注文でした。何社か見積もり取りましたが、見積もり方法が簡便、かつ安価。加工発送予定の連絡、丁寧で、且つ予定より早く発送され加工精度、梱包含め満足です。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'196',1,NULL,NULL,'2012-10-22 15:00:00','2012-10-22 15:00:00'),(5350,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'H.T',NULL,'アクリル板に10mmの孔を二箇所空けていただいたのですがひとつは9.9mmなので良いですがもうひとつは9.7mmで若干小さかったです。',4,NULL,NULL,'*.vectant.ne.jp',NULL,'197',1,NULL,NULL,'2012-10-22 15:00:00','2012-10-22 15:00:00'),(5351,'ポスターフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'a1',NULL,'UVカットの商品があるのは助かりました',5,NULL,NULL,'*.ocn.ne.jp',NULL,'198',1,NULL,NULL,'2012-10-24 15:00:00','2012-10-24 15:00:00'),(5352,'アクリル押出板',NULL,NULL,NULL,NULL,'エイシン',NULL,'家のベランダ日差部分のアクリルを交換したくて業者に見積もりだしていただいたら、15万円くらいかかるということでした。ネットで御社を見つけてアクリルを自分で図って135度曲げていただきました。届いて自分で交換したら見事にはまってくれて感動しました。値段も1/3でできて大変満足しております。',5,NULL,NULL,'*.bbtec.net',NULL,'199',1,NULL,NULL,'2012-10-21 15:00:00','2012-10-21 15:00:00'),(5353,'アクリル板加工　セミオーダー',NULL,NULL,NULL,NULL,'ルーク',NULL,'アクリル板のセミオーダーで寸法指定で切っていただきました。配送も早く助かりました。',4,NULL,NULL,'*.asahi-net.or.jp',NULL,'200',1,NULL,NULL,'2012-10-24 15:00:00','2012-10-24 15:00:00'),(5354,'アクリル押出板',NULL,NULL,NULL,NULL,'マスター',NULL,'お値打ちな商品でした。',4,NULL,NULL,'*.nagoya-c.ed.jp',NULL,'201',1,NULL,NULL,'2012-10-24 15:00:00','2012-10-24 15:00:00'),(5355,'箱型アクリルケース',NULL,NULL,NULL,NULL,'飲食店',NULL,'この度は面倒なアクリル円筒型の注文にも応じていただき、ありがとうございました。仕上がりもとても丁寧で大変満足です。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'202',1,NULL,NULL,'2012-10-25 15:00:00','2012-10-25 15:00:00'),(5356,'アクリル押出板',NULL,NULL,NULL,NULL,'yk',NULL,'透明アクリル板を額縁用に使用しました。特別にUVカットのアクリル板などは扱っておられますか？普通品と比較して価格などはどの程度違いがありますか？',4,NULL,NULL,'*.so-net.ne.jp',NULL,'203',1,NULL,NULL,'2012-10-24 15:00:00','2012-10-24 15:00:00'),(5357,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'ねお',NULL,'スティックポスターを飾るために購入しました。デザインも然ることながら密閉性も高く非常に重宝しています。今後とも機会があればよろしくお願いします。',5,NULL,NULL,'*.kinet-tv.ne.jp',NULL,'204',1,NULL,NULL,'2012-10-25 15:00:00','2012-10-25 15:00:00'),(5358,'アクリル押出板',NULL,NULL,NULL,NULL,'N',NULL,'品質もよく、満足しております。',4,NULL,NULL,'*.jp.panasonic.com',NULL,'205',1,NULL,NULL,'2012-10-25 15:00:00','2012-10-25 15:00:00'),(5359,'フォトフレーム　スタンダード',NULL,NULL,NULL,NULL,'lazio19',NULL,'いい商品だと思います。',5,NULL,NULL,'*.so-net.ne.jp',NULL,'206',1,NULL,NULL,'2012-10-27 15:00:00','2012-10-27 15:00:00'),(5360,'箱型アクリルケース',NULL,NULL,NULL,NULL,'KI-100',NULL,'航空機プラモデル収納展示用に200mm×200mm×100mmのケースとタイプBのディスプレイ台をセミオーダーした。セミオーダーだとタイプBの台を選択できるが、既存品のODC5はタイプAしか選べないのが少しだけ残念。価格の問題があるとは思うが。',5,NULL,NULL,'*.home.ne.jp',NULL,'207',1,NULL,NULL,'2012-10-27 15:00:00','2012-10-27 15:00:00'),(5361,'ポリカーボネート板',NULL,NULL,NULL,NULL,'Ko',NULL,'自作ポスターフレーム用に使用しました。梱包も丁寧にされていて完璧でした！',5,NULL,NULL,'*.tachikawa.mopera.net',NULL,'208',1,NULL,NULL,'2012-10-28 15:00:00','2012-10-28 15:00:00'),(5362,'アクリル球　クリアー',NULL,NULL,NULL,NULL,'ASC',NULL,'今のところ特になし。また、購入する予定。',4,NULL,NULL,'*.n-koei.co.jp',NULL,'209',1,NULL,NULL,'2012-10-28 15:00:00','2012-10-28 15:00:00'),(5363,'アクリル壁面棚',NULL,NULL,NULL,NULL,'hide',NULL,'二度目の購入になりますが、きれいに仕上がっていて満足しています',5,NULL,NULL,'*.plala.or.jp',NULL,'210',1,NULL,NULL,'2012-10-28 15:00:00','2012-10-28 15:00:00'),(5364,'アクリル円板加工　セミオーダー',NULL,NULL,NULL,NULL,'シャドーゾーン',NULL,'　理科の実験用に購入しました。震災の影響もあり、地学という科目が見直される中、アクリル円板を使ったシャドーゾーンの実験は今後ますます活発になっていくと思います。',5,NULL,NULL,'210.130.252.199',NULL,'211',1,NULL,NULL,'2012-10-29 15:00:00','2012-10-29 15:00:00'),(5365,'フルオーダー（特注）',NULL,NULL,NULL,NULL,'こん',NULL,'図面を送信しての特注品をお願いしました。切り込みの角の調整をご配慮いただいたりして、非常に精度の高いものができ、非常に満足しております。どうもありがとうございました。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'212',1,NULL,NULL,'2012-10-31 15:00:00','2012-10-31 15:00:00'),(5366,'アクリサンデー　接着剤',NULL,NULL,NULL,NULL,'Dr,Yan',NULL,'いつも完璧な商品ですので、安心してつかっています。ありがとうございます。',5,NULL,NULL,'*.vectant.ne.jp',NULL,'213',1,NULL,NULL,'2012-11-01 15:00:00','2012-11-01 15:00:00'),(5367,'CDフレーム',NULL,NULL,NULL,NULL,'ｆ。ｍｋ',NULL,'今回CDフレームを、お願いしました。でも実はジャケットを飾る為の購入ではありません。先日、あるライヴに行きまして、グッズ購入をしたのですが、そこでアーティストのサインが当たりました。これは日焼けしないように、またいつでも見れるように大切ににしなければ！と色紙額をさがしたのです。それでこちらのHPで紫外線対応の色紙額をみつけました。でも、当たった色紙はよく見る大きさのものではなく１/４位のものでした。通常の色紙額では余白部分が広すぎるし。飾っている内に斜めに傾かないか？などが気になり、だめか～と諦めかけたのですが。。ふと、その色紙CDの大きさを比べてみると、ほぼ一緒！これだ！と思い購入。まさにぴったり！　今はリビングにかっこよく飾られています。配送も早く、梱包の丁寧で嬉しかったです。ありがとうございました。',5,NULL,NULL,'*.yournet.ne.jp',NULL,'214',1,NULL,NULL,'2012-11-01 15:00:00','2012-11-01 15:00:00'),(5368,'厚物フレーム　セミオーダー',NULL,NULL,NULL,NULL,'匿名',NULL,'セミオーダーで厚物フレームを注文しましたが注文から発送まで早くてよかったです。',5,NULL,NULL,'*.ocn.ne.jp',NULL,'215',1,NULL,NULL,'2012-11-02 15:00:00','2012-11-02 15:00:00'),(5369,'アクリル押出板',NULL,NULL,NULL,NULL,'XENOUAV',NULL,'ちょっと高い',5,NULL,NULL,'*.ocn.ne.jp',NULL,'216',1,NULL,NULL,'2012-10-25 15:00:00','2012-10-25 15:00:00'),(5370,'箱型アクリルケース',NULL,NULL,NULL,NULL,'ティンカーベル',NULL,'指定通りの寸法で、且つ、角の合わせ部分が、みごとに接合されており、大満足です。',5,NULL,NULL,'*.bbtec.net',NULL,'217',1,NULL,NULL,'2012-11-02 15:00:00','2012-11-02 15:00:00'),(5371,'ユニフォーム額',NULL,NULL,NULL,NULL,'nobu',NULL,'この商品でこのお値段はお安いと思いました。また今後必要な時は購入させて頂こうと思います。ただ、重量がけっこう重いのでもう少し軽ければ言う事ありません。',4,NULL,NULL,'*.ocn.ne.jp',NULL,'218',1,NULL,NULL,'2012-11-03 15:00:00','2012-11-03 15:00:00'),(5372,'ポリカーボネート型模様板',NULL,NULL,NULL,NULL,'mack ',NULL,'表札として使用しました。トリマーで掘り、ブラックライトをあてたら、とてもきれいでした。ブラックライトは蛍光管の方がきれいに見えました。',5,NULL,NULL,'*.au-net.ne.jp',NULL,'219',1,NULL,NULL,'2012-11-04 15:00:00','2012-11-04 15:00:00'),(5373,'箱型アクリルケース',NULL,NULL,NULL,NULL,'chocosweet',NULL,'画像を添付し、同じ様にと依頼したのですが、到着した商品みて、Rがなく、角かくだったので残念でした。こちらは、素人なので、説明が難しかったので、あえて画像を添付したのに、せっかく作って頂いたのですが、希望者の要望をきちんと、聞き込んでいただく配慮が欲しかったです。今、二個目を注文してますが、連絡がないので、とても心配しています。',3,NULL,NULL,'*.ucom.ne.jp',NULL,'220',1,NULL,NULL,'2012-11-04 15:00:00','2012-11-04 15:00:00'),(5374,'アクリル押出板',NULL,NULL,NULL,NULL,'saitama',NULL,'サイズとか、完全にぴったりの物が来て驚いた。予想以上でした。',5,NULL,NULL,'*.odn.ad.jp',NULL,'221',1,NULL,NULL,'2012-11-02 15:00:00','2012-11-02 15:00:00'),(5375,'アクリル端材（薄板・厚板）',NULL,NULL,NULL,NULL,'とらきち',NULL,'アクリル成型品は価格が高い為、今回端財を購入しましたが、端財といっても形が揃っており、品質も良く大変満足です。ヒーターで曲げ加工をしてみましたが市販品に負けないくらいの仕上がりで大変満足です。',5,NULL,NULL,'*.infoweb.ne.jp',NULL,'222',1,NULL,NULL,'2012-11-04 15:00:00','2012-11-04 15:00:00'),(5376,'フォトフレーム　フロートタイプ',NULL,NULL,NULL,NULL,'shuhei',NULL,'商品のデザインや仕上がりはとても良い。ただ背面の壁面に固定する金具はもう少ししっかり固定できるタイプの方が望ましい。',4,NULL,NULL,'*.panda-world.ne.jp',NULL,'223',1,NULL,NULL,'2012-11-05 15:00:00','2012-11-05 15:00:00'),(5377,'ポスターフレーム　スタンダード',NULL,NULL,NULL,NULL,'Q太郎',NULL,'サイズがオーダーできたのでぴったりサイズに仕上がり家族全員喜んでいます',5,NULL,NULL,'*.ccnw.ne.jp',NULL,'22