n                                  <!--step 4-->\r\n                                  <section id=\"step-04\" class=\"l-article--column-1 c-flame--xs-semiorder\">\r\n                                    <h3 class=\"c-heading--md\">\r\n                                      <p class=\"heading__sub--before c-label--lg-primary\">STEP 4</p>サイズを入力\r\n                                    </h3>\r\n                                    <div class=\"l-article--column-2-reverse-center\">\r\n                                      <div class=\"article__content--w50\">\r\n                                        <div class=\"c-flame--xs-gray\">\r\n                                          <div class=\"flame__content\">\r\n                                            <dl class=\"section__set\">\r\n                                              <dt class=\"set__item\">横幅</dt>\r\n                                              <dd class=\"set__content\">\r\n                                                <div class=\"content__unit\">\r\n                                                  <p class=\"unit__inline\">\r\n                                                    <input name=\"width\" type=\"text\" id=\"width\" maxlength=\"6\" onChange=\"Chg();global_weight();\"><span>mm</span>\r\n                                                  </p>\r\n                                                </div>\r\n                                              </dd>\r\n                                            </dl>\r\n                                            <dl class=\"section__set\">\r\n                                              <dt class=\"set__item\">高さ</dt>\r\n                                              <dd class=\"set__content\">\r\n                                                <div class=\"content__unit\">\r\n                                                  <p class=\"unit__inline\">\r\n                                                    <input name=\"height\" type=\"text\" id=\"height\" maxlength=\"6\" onChange=\"Chg();global_weight();\"><span>mm</span>\r\n                                                  </p>\r\n                                                </div>\r\n                                              </dd>\r\n                                            </dl>\r\n                                            <dl class=\"section__set\" id=\"depth_area\">\r\n                                              <dt class=\"set__item\">奥行</dt>\r\n                                              <dd class=\"set__content\">\r\n                                                <div class=\"content__unit\" id=\"tc_depth\">\r\n                                                  <p class=\"unit__inline\">\r\n                                                    <input name=\"readonly_depth\" type=\"text\" id=\"readonly_depth\" tabindex=\"-1\" maxlength=\"12\" readonly class=\"content__number form__output\"><span>mm</span>\r\n                                                  </p>\r\n                                                </div>\r\n                                                <div class=\"content__unit\" id=\"k_depth\">\r\n                                                  <p class=\"unit__inline\">\r\n                                                    <input name=\"depth\" type=\"text\" id=\"depth\" maxlength=\"6\" onChange=\"Chg();global_weight();\"><span>mm</span>\r\n                                                  </p>\r\n                                                </div>\r\n                                              </dd>\r\n                                            </dl>\r\n                                            <dl class=\"section__set\">\r\n                                              <dt class=\"set__item\">板厚</dt>\r\n                                              <dd class=\"set__content\">\r\n                                                <div class=\"content__unit\" id=\"auto_t\">\r\n                                           