    <button type=\"button\" onclick=\"Form_Reset();Chg(1);\" class=\"c-button--sm-gray\">入力内容を全てリセット</button>\r\n                                  </div>\r\n                                </div>\r\n                              </div>\r\n                              <div class=\"detail__fullorder c-flame--xs-gray-column-2-vertical\">\r\n                                <div class=\"flame__content\">\r\n                                  <p class=\"c-text--sm-weightBold\">セミオーダーでご希望の仕様が指定できない場合、フルオーダーにてお問い合わせ下さい。</p>\r\n                                </div>\r\n                                <div class=\"flame__content\"><a href=\"/full_order/\" target=\"_blank\" class=\"c-button--sm-primary u-width--100\">詳細はこちら<i class=\"button__icon--after c-icon--arrow-r-white\"></i></a></div>\r\n                              </div>\r\n                              {%revision_history%}\r\n                            </div>\r\n                          </div>\r\n                        </form>\r\n\r\n    <script>\r\n      window.onload = function() {\r\n        Chg();\r\n      };\r\n\r\n    </script>','2020-11-27 07:55:27','2020-11-27 07:55:30'),(66,428,NULL,'2020-11-28 04:05:40','2020-11-28 04:05:40'),(67,429,NULL,'2020-11-30 07:26:26','2020-11-30 07:26:26'),(68,430,'<form name=\"form1\" id=\"form1\" method=\"post\" action=\"/cgibin/cart-n/ex/cart.cgi\" onsubmit=\"return false;\" class=\"p-overview--semiorder c-form js-scrollFixed\">\r\n  <!-- デフォルトパラメーター-->\r\n  <div>\r\n    <script type=\"text/javascript\">document.write(\'<input type=\"hidden\" name=\"url\" id=\"url\" value=\"\' + location.href + \'\" />\');</script>\r\n    <input id=\"itemna\" name=\"itemna\" type=\"HIDDEN\" value=\"PET板 コの字曲げ加工 セミオーダー\">\r\n    <input id=\"itemno\" name=\"itemno\" type=\"HIDDEN\" value=\"semi_konoji\">\r\n    <input id=\"itemsh\" type=\"HIDDEN\" name=\"itemsh\">\r\n    <input id=\"size\" name=\"size\" type=\"HIDDEN\">\r\n    <input id=\"opt1\" name=\"opt1\" type=\"HIDDEN\">\r\n    <input id