                                             <div id=\"ana_m_kei2_disp\" class=\"form__select u-width--100\">\r\n                                                            <select name=\"ana_m_kei2\" id=\"ana_m_kei2\" onChange=\"preChg();Chg();\"></select>\r\n                                                          </div>\r\n                                                        </div>\r\n                                                        <div id=\"ana_open2\" class=\"content__unit\">\r\n                                                          <p class=\"unit__inline\"><span>直径</span>\r\n                                                            <input name=\"ana_kei2\" id=\"ana_kei2\" type=\"text\" onChange=\"preChg();Chg();\" maxlength=\"5\"><span>mm</span>\r\n                                                          </p>\r\n                                                        </div>\r\n                                                        <div class=\"content__unit\">\r\n                                                          <div class=\"form__select u-width--100\">\r\n                                                            <select name=\"ana_m_suu2\" id=\"ana_m_suu2\" onChange=\"preChg();Chg();\">\r\n                                                              <option value=\"\" selected>位置選択</option>\r\n                                                              <option value=\"A\">A</option>\r\n                                                              <option value=\"B\">B</option>\r\n                                                              <option value=\"C\">C</option>\r\n                                                              <option value=\"D\">D</option>\r\n                                                              <option value=\"AB\">AB</option>\r\n                                                              <option value=\"AC\">AC</option>\r\n                                                              <option value=\"AD\">AD</option>\r\n                                                              <option value=\"BC\">BC</option>\r\n                                                              <option value=\"BD\">BD</option>\r\n                                                              <option value=\"DC\">DC</option>\r\n                                                              <option value=\"ABC\">ABC</option>\r\n                                                              <option value=\"ABD\">ABD</option>\r\n                                                              <option value=\"ACD\">ACD</option>\r\n                                                              <option value=\"BCD\">BCD</option>\r\n                                                              <option value=\"ABCD\">ABCD</option>\r\n                                                            </select>\r\n                                                          </div>\r\n                                                        </div>\r\n                                                      </div>\r\n                                                      <div class=\"content__sub\">\r\n                                                        <div class=\"content__unit\">\r\n                                                          <p class=\"unit__inline\"><span>X</span>\r\n                                                            <input name=\"ana_m_x2\" type=\"text\" id=\"ana_m_x2\" onChange=\"preChg();Chg();\" maxlength=\"5\"><span>mm</span>\r\n                                                          </p>\r\n                                                        </div>\r\n                                                        <div class=\"content__unit\">\r\n                                                          <p class=\"unit__inline\"><span>Y</span>\r\n                                                            <input name=\"ana_m_y2\" type=\"text\" id=\"ana_m_y2\" onChange=\"preChg();Chg();\" maxlength=\"5\"><span>mm</span>\r\n                                                          </p>\r\n                                                        </div>\r\n                                                      </div>\r\n                                                    </dd>\r\n                                                  </dl>\r\n                                                </div>\r\n                                                <div class=\"c-flame--xs-gray js-addContent__content\">\r\n                                                  <dl class=\"section__set\">\r\n                                                    <dt class=\"set__item u-width--3rem\">3/3</dt>\r\n                                                    <dd class=\"set__content\">\r\n                                                      <div class=\"content__sub\">\r\n                                                        <div class=\"content__unit\">\r\n                                                          <div class=\"form__select u-width--100\">\r\n                                                            <select name=\"ana_m_type3\" id=\"ana_m_type3\"  onChange=\"preChg();Chg();\"></select>\r\n                                                          </div>\r\n                                                        </div>\r\n                                                        <div class=\"content__unit\">\r\n                                                          <div id=\"ana_m_kei3_disp\" class=\"form__select u-width--100\">\r\n                                                            <select name=\"ana_m_kei3\" id=\"ana_m_kei3\" onChange=\"preChg();Chg();\"></select>\r\n                                                          </div>\r\n                                                        </div>\r\n                                                        <div id=\"ana_open3\" class=\"content__unit\">\r\n                                                          <p class=\"unit__inline\"><span>直径</span>\r\n                                                            <input name=\"ana_kei3\" id=\"ana_kei3\" type=\"text\" onChange=\"preChg();Chg();\" maxlength=\"5\"><span>mm</span>\r\n                                                          </p>\r\n                                                        </div>\r\n                                                        <div class=\"content__unit\">\r\n                                                          <div class=\"form__select u-width--100\">\r\n                                                            <select name=\"ana_m_suu3\" id=\"ana_m_suu3\" onChange=\"preChg();Chg();\">\r\n                                                              <option value=\"\" selected>位置選択</option>\r\n                                                              <option value=\"A\">A</option>\r\n                                                              <option value=\"B\">B</option>\r\n                                                              <option value=\"C\">C</option>\r\n                                                              <option value=\"D\">D</option>\r\n                                                              <option value=\"AB\">AB</option>\r\n                                                              <option value=\"AC\">AC</option>\r\n                                                              <option value=\"AD\">AD</option>\r\n                                                              <option value=\"BC\">BC</option>\r\n                                                              <option value=\"BD\">BD</option>\r\n                                                              <option value=\"DC\">DC</option>\r\n                                                              <option value=\"ABC\">ABC</option>\r\n                                                              <option value=\"ABD\">ABD</option>\r\n                                                              <option value=\"ACD\">ACD</option>\r\n                                                              <option value=\"BCD\">BCD</option>\r\n                                                              <option value=\"ABCD\">ABCD</option>\r\n                                                            </select>\r\n                                                          </div>\r\n                                                        </div>\r\n                                                      </div>\r\n                                                      <div class=\"content__sub\">\r\n                                                        <div class=\"content__unit\">\r\n                                                          <p class=\"unit__inline\"><span>X</span>\r\n                                                            <input name=\"ana_m_x3\" type=\"text\" id=\"ana_m_x3\" onChange=\"preChg();Chg();\" maxlength=\"5\"><span>mm</span>\r\n                                                          </p>\r\n                                                        </div>\r\n                                                        <div class=\"content__unit\">\r\n                                                          <p class=\"unit__inline\"><span>Y</span>\r\n                                                            <input name=\"ana_m_y3\" type=\"text\" id=\"ana_m_y3\" onChange=\"preChg();Chg();\" maxlength=\"5\"><span>mm</span>\r\n                                                          </p>\r\n                                                        </div>\r\n                                                      </div>\r\n                                                    </dd>\r\n                                                  </dl>\r\n                                                </div>\r\n\r\n\r\n\r\n                                                <div class=\"section__buttonSet\">\r\n                                                  <button type=\"button\" class=\"buttonSet__add c-button--xs-primary js-addContent__trigger--add\">加工を追加する</button>\r\n                                                  <button type=\"button\" onclick=\"h_clear()\" class=\"buttonSet__clear c-button--xs-gray\">クリア</button>\r\n                                                </div>\r\n                                              </div>\r\n                                              <div class=\"article__content--w40\">\r\n                                                <div class=\"content__inputNum\"><img src=\"/assets/images/products/semi_order/9/img_option2_01.jpg\">\r\n                                                  <input name=\"tate_a\" type=\"text\" id=\"tate_a\" tabindex=\"-1\" maxlength=\"6\" class=\"inputNum__tate\">\r\n                                                  <input name=\"yoko_a\" type=\"text\" id=\"yoko_a\" tabindex=\"-1\" maxlength=\"6\" class=\"inputNum__yoko\">\r\n                                                </div>\r\n                                              </div>\r\n                                            </div>\r\n                                            <div class=\"l-article--column-1\">\r\n                                              <div class=\"article__content js-accordion\"><a class=\"js-accordion__trigger\"><i class=\"c-icon--toggle\"></i>穴加工形状に関する詳細</a>\r\n                                                <div class=\"js-accordion__content\">\r\n                                                  <div class=\"l-article--column-2-vertical\">\r\n                                                    <div class=\"article__content--w40\"><img src=\"/assets/images/products/semi_order/9/img_option2_04.jpg\" class=\"js-modal--image\"></div>\r\n                                                    <div class=\"article__content--w60\">\r\n                                                      <h4 class=\"c-heading--sm\">丸穴（貫通穴）</h4>\r\n                                                      <ul class=\"c-list--disc\">\r\n                                                        <li class=\"list__item\">ストレートの貫通穴（※キリ穴）</li>\r\n                                                        <li class=\"list__item\">直径は1～960mm、小数点第1位まで入力可能<br>（例：φ4.2、φ8.7など）</li>\r\n                                                      </ul>\r\n                                                    </div>\r\n                                                  </div>\r\n                                                  <div class=\"l-article--column-2-vertical\">\r\n                                                    <div class=\"article__content--w40\"><img src=\"/assets/images/products/semi_order/9/img_option2_05.jpg\" class=\"js-modal--image\"></div>\r\n                                                    <div class=\"article__content--w60 js-modal\">\r\n                                                      <h4 class=\"c-heading--sm\">タップ穴（ネジ穴）</h4>\r\n                                                      <ul class=\"c-list--disc\">\r\n                                                        <li class=\"list__item\">ネジを固定できるメスネジ山付きの貫通穴</li>\r\n                                                        <li class=\"list__item\">M3～M8まで入力可能</li>\r\n                                                      </ul><a data-target=\"hole-02\" class=\"c-button--xs-gray js-modal__trigger--open\">詳細寸法</a>\r\n                                                      <div id=\"hole-02\" class=\"c-window--md js-modal__content\"><img src=\"/assets/images/products/semi_order/9/img_option2_06.jpg\"></div>\r\n                                                    </div>\r\n                                                  </div>\r\n                                                  <div class=\"l-article--column-2-vertical\">\r\n                                                    <div class=\"article__content--w40\"><img src=\"/assets/images/products/semi_order/9/img_option2_07.jpg\" class=\"js-modal--image\"></div>\r\n                                                    <div class=\"article__content--w60 js-modal\">\r\n                                                      <h4 class=\"c-heading--sm\">サラザグリ（皿穴）</h4>\r\n                                                      <ul class=\"c-list--disc\">\r\n                                                        <li class=\"list__item\">サラネジの頭を板の平面に合わせて平らに固定する貫通穴</li>\r\n                                                        <li class=\"list__item\">M3～M8まで入力可能</li>\r\n                                                      </ul><a data-target=\"hole-03\" class=\"c-button--xs-gray js-modal__trigger--open\">詳細寸法</a>\r\n                                                      <div id=\"hole-03\" class=\"c-window--md js-modal__content\"><img src=\"/assets/images/products/semi_order/9/img_option2_08.jpg\"></div>\r\n                                                    </div>\r\n                                                  </div>\r\n                                                  <div class=\"l-article--column-2-vertical\">\r\n                                                    <div class=\"article__content--w40\"><img src=\"/assets/images/products/semi_order/9/img_option2_09.jpg\" class=\"js-modal--image\"></div>\r\n                                                    <div class=\"article__content--w60 js-modal\">\r\n                                                      <h4 class=\"c-heading--sm\">キャップボルトザグリ（平ザグリ）</h4>\r\n                                                      <ul class=\"c-list--disc\">\r\n                                                        <li class=\"list__item\">キャップボルトの頭を板に埋没させる段付き貫通穴</li>\r\n                                                        <li class=\"list__item\">M3～M8まで入力可能</li>\r\n                                                      </ul><a data-target=\"hole-04\" class=\"c-button--xs-gray js-modal__trigger--open\">詳細寸法</a>\r\n                                                      <div id=\"hole-04\" class=\"c-window--md js-modal__content\"><img src=\"/assets/images/products/semi_order/9/img_option2_10.jpg\"></div>\r\n                                                    </div>\r\n                                                  </div>\r\n                                                </div>\r\n                                              </div>\r\n                                              <div class=\"article__content js-accordion\"><a class=\"js-accordion__trigger\"><i class=\"c-icon--toggle\"></i>入力に関する詳細</a>\r\n                                                <div class=\"js-accordion__content\">\r\n                                                  <ul class=\"c-list--disc\">\r\n                                                    <li class=\"list__item\">穴の淵が端面から近い場合は指定できません。</li>\r\n                                                    <li class=\"list__item\">選択できない使用ネジサイズは指定できません。</li>\r\n                                                    <li class=\"list__item\">板の厚みが1mmの場合、丸穴以外は指定できません。</li>\r\n                                                    <li class=\"list__item\">穴の断面は細目仕上になります（磨き仕上は不可）。</li>\r\n                                                  </ul>\r\n                                                </div>\r\n                                              </div>\r\n                                            </div>\r\n                                          </div>\r\n                                        </section>\r\n          </section>\r\n          <!--step 6-->\r\n          <section id=\"step-06\" class=\"l-article--column-1 c-flame--xs-semiorder\">\r\n            <h3 class=\"c-heading--md\">\r\n              <p class=\"heading__sub--before c-label--lg-primary\">STEP 6</p>印刷設定を選択\r\n            </h3>\r\n            <div class=\"l-article--column\">\r\n              <div class=\"article__content\">\r\n                <img id=\"imgprintSetting\" src=\"/storage/images/uvPrint/plate/imgprintSetting011.jpg\">\r\n              </div>\r\n            </div>\r\n            <div class=\"l-article--column\">\r\n              <div class=\"article__content--w50\">\r\n                <div class=\"c-flame--xs-gray\">\r\n                  <dl class=\"section__set\">\r\n                    <dt class=\"set__item\">全面印刷 </dt>\r\n                    <dd class=\"set__content\">\r\n                      <div class=\"content__unit\">\r\n                        <div class=\"form__select u-width--100\">\r\n                          <select name=\"fullsurface\" id=\"fullsurface\" onchange=\"preChg();Chg();\">\r\n                            <option value=\"1\">する</option>\r\n                            <option value=\"0\" selected=\"\">しない</option>\r\n                          </select>\r\n                        </div>\r\n                      </div>\r\n                      <p class=\"content__note\" id=\"whiteNote\">全面印刷（フチ無し印刷）には塗り足し3ｍｍ以上が必要です。詳細は<a href=\"/naire_order/uv/nuritashi/\" target=\"_blank\">塗り足しについて</a>をご確認下さい。</p>\r\n                    </dd>\r\n                  </dl>\r\n                  <dl class=\"section__set\">\r\n                    <dt class=\"set__item\">白版</dt>\r\n                    <dd class=\"set__content\">\r\n                      <div class=\"content__unit\">\r\n                        <div class=\"form__select u-width--100\">\r\n                          <select name=\"wprinting\" id=\"wprinting\" onchange=\"preChg();Chg();\">\r\n                            <option value=\"0\">有り</option>\r\n                            <option value=\"2\">全面白</option>\r\n                            <option value=\"1\">無し</option>\r\n                          </select>\r\n                        </div>\r\n                      </div>\r\n                      <p class=\"content__note\" id=\"whiteNote\">ホワイト、ホワイト両面マットの場合、白版無しでも鮮やかな発色が可能です。</p>\r\n                    </dd>\r\n                  </dl>\r\n                  <dl class=\"section__set\">\r\n                    <dt class=\"set__item\">印刷面 </dt>\r\n                    <dd class=\"set__content\">\r\n                      <div class=\"content__unit\">\r\n                        <div class=\"form__select u-width--100\">\r\n                          <select name=\"side\" id=\"side\" onchange=\"preChg();Chg();\">\r\n                            <option value=\"0\">背面</option>\r\n                            <option value=\"1\">前面</option>\r\n                          </select>\r\n                        </div>\r\n                      </div>\r\n                    </dd>\r\n                  </dl>\r\n                </div>\r\n                <ul class=\"c-list--disc\">\r\n                  <li class=\"list__item\">詳細は<a href=\"#uvdetail\" class=\"c-link js-anchorScroll\">UVインクジェット印刷仕様</a>をご確認ください。</li>\r\n                </ul>\r\n              </div>\r\n              <div class=\"article__content--w50\">\r\n              </div>\r\n            </div>\r\n          </section>\r\n          <!--step 7-->\r\n          <section id=\"step-07\" class=\"l-article--column-1 c-flame--xs-semiorder\">\r\n            <h3 class=\"c-heading--md\">\r\n              <p class=\"heading__sub--before c-label--lg-primary\">STEP 7</p>シミュレーターでデザイン\r\n            </h3>\r\n            <div class=\"l-article--column\">\r\n              <div class=\"article__content\">\r\n                <ul class=\"c-list\">\r\n                  <li class=\"list__item__red\">シミュレーター画面遷移後はSTEP2～6の入力内容、数量変更は出来ません。</li>\r\n                </ul>\r\n                <ul class=\"c-list--disc\">\r\n                  <li class=\"list__item\">「仕様・数量を確認しました」にチェックを入れていただき、「デザインをつくる」ボタンを押してください。</li>\r\n                  <li class=\"list__item\">著作権や肖像権などを侵害するおそれのある写真やデザイン、残虐的・猟奇的な表現や刑法175条に抵触するおそれのあるわいせつなものに加え、芸術品や展示目的であっても裸や露出の高いデザインは、弊社の判断によりお断りする場合がございます。</li>\r\n                </ul>\r\n                <ul class=\"c-list\">\r\n                  <li class=\"list__item__red\">入稿データの純白部分にご注意ください</li>\r\n                </ul>\r\n                <ul class=\"c-list--disc\">\r\n                  <li class=\"list__item\">純白の箇所は非印刷扱いとなります。意図しない仕上がりを防ぐため、ご入稿前に必ず<a href=\"/naire_order/uv/whitejudge/\" target=\"_blank\">100%白判定ツール</a>でのチェックをお願いいたします。</li>\r\n                </ul>\r\n              </div>\r\n            </div>\r\n            <div class=\"c-flame--xs-gray-column-2-center\" id=\"detailChk\">\r\n              <div class=\"flame__content\">\r\n                <p class=\"c-text--center\">\r\n                  <label class=\"form__checkbox c-text--md-weightBold\">\r\n                    <input id=\"drawing_check\" name=\"drawing_check\" type=\"checkbox\" disabled=\"\" value=\"1\"><i class=\"appearance\"></i>\r\n                  </label>\r\n                  <label class=\"form__checkbox c-text--md-weightBold\">\r\n                    <input id=\"suryoCheck\" name=\"suryoCheck\" type=\"checkbox\" value=\"1\"><i\r\n                      class=\"checkbox__button\"></i>仕様・数量を確認しました\r\n                  </label>\r\n                </p>\r\n              </div>              <div class=\"flame__content\">\r\n                <button type=\"button\" value=\"シミュレーター\" onClick=\"submitSimulator();\" class=\"c-button--md-zumen u-width--100 zumenn\">デザインをつくる</button>\r\n              </div>\r\n            </div>\r\n          </section>\r\n          <!--step 8-->\r\n          <section id=\"step-08\" class=\"l-article--column-1 c-flame--xs-semiorder\">\r\n            <h3 class=\"c-heading--md\">\r\n              <p class=\"heading__sub--before c-label--lg-primary\">STEP 8</p>デザイン・内容の最終確認\r\n            </h3>\r\n            <div class=\"l-article--column\">\r\n              <div class=\"article__content\">\r\n                <div class=\"c-flame--xs-gray-column-2-vertical\">\r\n                  <div class=\"flame__content--50\">\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">アクリル色</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"plateColor\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">厚み</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"plateThickness\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p><span>mm</span>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">横ｘ縦</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"plateSize\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p><span>mm</span>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">切断端面</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"plateFraise\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                  </div>\r\n                  <div class=\"flame__content--50\">\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">全面印刷</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"printAll\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">白版</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"printWhite\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">印刷面</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"plateSurface\">\r\n                            <input type=\"text\" class=\"content__number form__output\">\r\n                          </p>\r\n                        </div>\r\n                      </dd>\r\n                    </dl>\r\n                    <dl class=\"section__set\">\r\n                      <dt class=\"set__item u-width--100\">数量</dt>\r\n                      <dd class=\"set__content\">\r\n                        <div class=\"content__unit\">\r\n                          <p class=\"unit__inline\" id=\"plateSuu\">\r\n                            <input type=\"text\" class=\"content__numb