--
-- Table structure for table `specification_detail_individuals`
--

DROP TABLE IF EXISTS `specification_detail_individuals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `specification_detail_individuals` (
  `specification_detail_individual_id` bigint NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `is_default_display` tinyint(1) DEFAULT NULL COMMENT '1:表示\r\n0:非表示',
  `color_id` bigint unsigned DEFAULT NULL,
  `size_id` bigint unsigned DEFAULT NULL,
  `plate_thickness_id` bigint unsigned DEFAULT NULL,
  `product_option_content_id` bigint unsigned DEFAULT NULL,
  `product_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品コード',
  `price` bigint DEFAULT NULL COMMENT '定価',
  `product_name_displayed_cart` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivery_schedule_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '発送予定がまとめられたCSVファイルの4行目の値をセットする',
  `is_destination_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `is_delivery_charge_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `delivery_private_price` int unsigned DEFAULT NULL,
  `delivery_faraway_price` int unsigned DEFAULT NULL,
  `is_large_delivery_valid` tinyint(1) DEFAULT NULL COMMENT '1:有効\r\n0:無効',
  `memo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL COMMENT '論理削除用\r\n日付が入っている場合は論理削除',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`specification_detail_individual_id`),
  KEY `idx_specification_detail_individuals_01` (`product_id`),
  KEY `idx_specification_detail_individuals_02` (`color_id`),
  KEY `idx_specification_detail_individuals_03` (`size_id`),
  KEY `idx_specification_detail_individuals_04` (`plate_thickness_id`),
  CONSTRAINT `specification_detail_individuals_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3457 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

